// ramana_te.dart
// Maharishi Ramana quotes and articles (Malyalam)

import '../articlesquotes.dart';

final ramanaSaint = Saint(
  'raman',
  'മഹർഷി രമണ',
  'assets/images/raman.jpg',
  [
    'നിങ്ങളുടെ ആത്മസാക്ഷാത്കാരം ലോകത്തിന് നൽകാവുന്ന ഏറ്റവും വലിയ സേവനമാണ്.',
    'സൃഷ്ടിയും നാശവും ഇല്ല, വിധിയും സ്വതന്ത്ര ഇച്ഛയും ഇല്ല, മാർഗ്ഗവും സാദ്ധ്യവും ഇല്ല. ഇതാണ് അന്തിമ സത്യം.',
    'സന്തോഷം നിങ്ങളുടെ സ്വഭാവമാണ്. അതിനെ ആഗ്രഹിക്കുന്നത് തെറ്റല്ല. തെറ്റുള്ളത് അതിനെ അകത്താണ് ഉള്ളത് എന്നിരിക്കെ പുറത്തു തേടുകയാണ്.',
    '"ഞാൻ ആരാണ്?" എന്ന ചോദ്യത്തിന്‍റെ ആലോചന എല്ലാ മറ്റു ചോദ്യങ്ങളെയും നശിപ്പിക്കും.',
    'സ്വന്തം യഥാർത്ഥ സ്വഭാവത്തെ കണ്ടെത്താതെ ലോകത്തെ പരിഷ്കരിക്കാൻ ആഗ്രഹിക്കുന്നത്, കല്ലുകളിലും മുള്ളുകളിലും നടക്കുമ്പോൾ അനുഭവിക്കുന്ന വേദന ഒഴിവാക്കാൻ ലോകത്തെ മുഴുവനും തുകൽകൊണ്ട് മൂടാൻ ശ്രമിക്കുന്നതുപോലെയാണ്.',
    'നിശ്ശബ്ദതയും ഒരു സംവാദമാണ്.',
    'മനസ്സെന്നത് ചിന്തകളുടെ സമാഹാരമാണ്. ചിന്തകളെ നിർത്തി, മനസ്സിനെ എനിക്കു കാണിക്കൂ.',
    'ഇപ്പൊഴുള്ള ജന്മത്തിന്റെ ഏക പ്രയോജനകരമായ ലക്ഷ്യം അകത്തേക്ക് തിരിഞ്ഞ് ആത്മസാക്ഷാത്കാരം നേടുക എന്നതാണ്.',
    'യാതൊരു ശ്രമവും കൂടാതെ ആരും വിജയിക്കുന്നില്ല. വിജയിക്കുന്നവർ അവരുടെ വിജയം സഹനശക്തിക്കും സ്ഥിരതയ്ക്കും കടപ്പെട്ടവരാണ്.',
    'വരുന്നത് വരട്ടെ. പോകുന്നത് പോകട്ടെ. ശേഷിക്കുന്നതു എന്താണെന്ന് കണ്ടെത്തുക.',
    '\'ഞാൻ ആരാണ്?\' എന്ന ചോദ്യം ഒരു മാനസിക വ്യായാമമല്ല. അത് ആത്മീയ അഭ്യാസത്തിന്റെ ഉന്നത രൂപമാണ്.',
    '\'ഞാൻ\' എന്ന ചിന്തയാണ് എല്ലാ ചിന്തകളുടെയും മൂലകം. അതിനെ പിടിച്ചു അതിന്റെ ഉറവിടത്തിലേക്ക് പിന്തുടരുന്നത് എല്ലാ ചിന്തകളെയും നശിപ്പിക്കുന്ന ഏക മാർഗ്ഗമാണ്.',
    'ആത്മാവ് എപ്പോഴും സന്നിഹിതമാണ്. അതിനെ തേടേണ്ട ആവശ്യമില്ല, ആത്മാവല്ലാത്തതിനെ തേടുന്നത് നിർത്തുക മാത്രം മതി.',
    'അവസാന സത്യം ഇതാണ്: \'ഞാൻ\' ഒരു ചിന്തയല്ല; അത് ബോധം തന്നെയാണ്.',
    'ആത്മാവിനെ തിരിച്ചറിയാൻ ആവശ്യമായത് നിശ്ചലതയാണ്.',
    'നീ ആത്മാവാണ്. അതായിരിക്കുക.',
    '\'ഞാൻ ആരാണ്?\' എന്ന് ചോദിക്കുന്നത് മനസ്സിനെ അകത്തേക്ക് തിരിച്ച് ആഴത്തിൽ ഉറവിടത്തിലേക്ക് മുങ്ങുക എന്നതാണ്.',
    'പാമ്പിനെ പോലെ, അഹങ്കാരം ആത്മാവിൽ മാത്രമേ കാണപ്പെടുന്നുള്ളൂ.',
    'അഹങ്കാരം മനസ്സാണ്. മനസ്സാണ് എല്ലാ ആഗ്രഹങ്ങളുടെ ഉറവിടം.',
    'അഹങ്കാരം യഥാർത്ഥമായ ഒരു സത്വമല്ല. അത് ഒരു ചിന്താരൂപമാണ്, ആത്മയുടെ പ്രകാശം തെളിയുമ്പോൾ അപ്രത്യക്ഷമാകുന്ന ഒരു നിഴൽ.',
    'മനം ഒരു മായയാണ്. അത് ചിന്തകളുടെ ഒരു കൂട്ടം മാത്രമാണ്.',
    'മനസ്സ് ശമിക്കുമ്പോൾ ആത്മാവ് അനുഭവപ്പെടുന്നു. മനസ്സാണ് തടസ്സം.',
    'ബോധ്യം ഒരു പുതിയ സമ്പാദ്യം അല്ല. അത് നിങ്ങളുടെ നിത്യ സ്വഭാവത്തിന്റെ പുനരാവിഷ്കാരമാണ്.',
    'ശരീരവും മനസ്സും നിങ്ങൾ അല്ല. നിങ്ങൾ ഇരുവിനെയും സാക്ഷിയായി കാണുന്നവനാണ്.',
    '\'ഞാൻ\' എന്ന ചിന്ത അപ്രത്യക്ഷമാകുമ്പോൾ, മറ്റ് എല്ലാ ചിന്തകളും അതിനൊപ്പം അപ്രത്യക്ഷമാകുന്നു.',
    'മൗനം ആത്മീയ ഉപദേശത്തിന്റെ ഏറ്റവും ശക്തമായ രൂപമാണ്.',
    'ഏറ്റവും ഉത്തമമായ ആത്മീയ അഭ്യാസം ശാന്തതയിൽ നിലകൊള്ളുന്നതാണ്.',
    'ബോധ്യം നേടേണ്ട ഒന്നല്ല; ചിന്തകളുടെ അഭാവത്തിൽ വെളിപ്പെടേണ്ട ഒന്നാണ്.',
    'ഹൃദയത്തിന്റെ നിശ്ശബ്ദത ഏതൊരു വാക്കിനേക്കാളും വാഗ്മിയായിരിക്കുന്നു.',
    'യഥാർത്ഥ ജ്ഞാനം ബുദ്ധിയിൽ അല്ല; അത് ഹൃദയത്തിലാണ്, നിശ്ശബ്ദതയിൽ വെളിപ്പെടുന്നതും ആകുന്നു.',
    'അവസാന നില മൗനത്തിന്റെ നിലയാണ്, അവിടെ \'ഞാൻ\' അല്ലെങ്കിൽ \'നീ\' എന്നതില്ല.',
    'ആത്മാവ് പൂർണ്ണമായ ശാന്തതയിൽ സാക്ഷാത്കരിക്കപ്പെടുന്നു.',
    'നിശ്ചലതയാണ് പ്രാർത്ഥനയുടെ ഉന്നത രൂപം.',
    'യഥാർത്ഥ സമാധാനം എല്ലാ ചിന്തകളുടെയും അഭാവമാണ്.',
    'ധ്യാനം ദൈവത്തെ കുറിച്ച് ചിന്തിക്കുന്നതല്ല, മറിച്ച് ശാന്തമായ അവസ്ഥയിൽ നിലനിൽക്കുന്നതാണ്, അതാണ് ദൈവം.',
    'മനസ്സ് ഒരു അശാന്തമായ കുരങ്ങാണ്. അതിനെ ശാന്തമാക്കാനുള്ള ഏക മാർഗം നിശ്ചലതയിലാണ്.',
    'നിശ്ശബ്ദതയാണ് ആത്മാവിന്റെ ശാശ്വതാവസ്ഥ.',
    'നിശ്ശബ്ദതയിൽ കൂടുതൽ ആഴപ്പെട്ടാൽ, സത്യത്തെ കൂടുതൽ മനസ്സിലാക്കാൻ കഴിയും.',
    'നിശ്ശബ്ദത എന്നത് ശബ്ദത്തിന്റെ അഭാവമല്ല, മറിച്ച് ശാന്തതയുടെ സാന്നിധ്യമാണ്.',
    'യഥാർത്ഥ പ്രാർത്ഥന എന്നത് ശാന്തമായി നിന്നുകൊണ്ട് \'ഞാൻ ആകുന്നു\' എന്ന് അറിയുന്നതാണ്.',
    'ദൈവം ഒരു ബാഹ്യ സത്തയല്ല. ദൈവം ആത്മാവാണ്.',
    'ലോകം മായയാണ്. ആത്മാവേ ഏക യാഥാർത്ഥ്യം.',
    'നിങ്ങൾ കാണുന്ന എല്ലാം ദൈവമാണ്. നിങ്ങൾ കേൾക്കുന്ന എല്ലാം ദൈവമാണ്.',
    'ലോകം മനസ്സിന്റെ പ്രതിഫലനം മാത്രമാണ്.',
    'സ്വയം എന്നതിൽ നിന്ന് വേറിട്ട യാഥാർത്ഥ്യം ഇല്ല.',
    'ലോകം നിന്നിൽ നിന്ന് വേർപെട്ട ഒന്നല്ല.',
    'നീ ആണ്ടവസത്തിൽ അല്ല, ആണ്ടവസം നിനക്കുള്ളിൽ ആണ്.',
    'യഥാർത്ഥ സത്യം ആത്മാവാണ്. ലോകം, അഹങ്കാരം, ദൈവം എല്ലാം ആത്മാവിൽ തന്നെയാണ്.',
    'ലോകം ഒരു സ്വപ്നമാണ്. സ്വപ്നം കാണുന്നവൻ ആത്മാവാണ്.',
    'ദൈവം എല്ലാറ്റിന്റെയും ഉറവിടം, എല്ലാറ്റിനെയും സാക്ഷീകരിക്കുന്നവൻ, എല്ലാറ്റിന്റെയും യാഥാർത്ഥ്യമാണ്.',
    'ഒന്നേയൊരു യാഥാർത്ഥ്യമുണ്ട്, അത് ചൈതന്യമത്രേ.',
    'ദൈവം സ്നേഹമാണ്. സ്നേഹം ആത്മാവിന്റെ പ്രകാശമാണ്.',
    'ലോകം ഒരു ആശയമാണ്. ഏക സത്യം ആത്മാവാണ്.',
    'ലോകം ദൈവത്തിന്റെ പ്രതിഫലനമാണ്, എന്നാൽ ദൈവം ലോകത്താൽ പരിധിയില്ല.',
    'ആത്മാവ് എല്ലാ സത്തയുടെയും അടിസ്ഥാനമാണ്.',
    'ക്രിയ itself ബന്ധത്തിന്റെ കാരണം അല്ല; കർത്തൃത്വബോധമാണ്.',
    'യഥാർത്ഥ പ്രവർത്തി പ്രയാസമില്ലാതെ സ്വാഭാവികമായി സംഭവിക്കുന്നു. അത് സത്താവസ്ഥയിൽ നിന്ന് ഒഴുകിയെത്തുന്നു.',
    'നിന്റെ പ്രവർത്തികളുടെ ഫലത്തെക്കുറിച്ച് ആശങ്കപ്പെടേണ്ടതില്ല. ആത്മാവ് എല്ലാം ശ്രദ്ധിക്കും.',
    'കർത്തൃത്വബോധം ഇല്ലാതെ ചെയ്യുന്ന പ്രവർത്തി മോക്ഷത്തിലേക്ക് നയിക്കുന്നു.',
    'കർമ്മം കാരണം-ഫലങ്ങളുടെ ഒരു ശൃംഖലയാണ്, എന്നാൽ ആത്മാവ് കർമ്മത്തിൽ നിന്ന് സ്വതന്ത്രമാണ്.',
    'ലോകത്തിൽ ജീവിക്കൂ, പക്ഷേ ലോകത്തിന്റേതായി അല്ല.',
    'കര്‍മ്മത്തില്‍നിന്ന് മോചനം നേടാനുള്ള ഏക മാര്‍ഗ്ഗം ആത്മാവിനെ തിരിച്ചറിയുക എന്നതാണ്.',
    'ഫലങ്ങളിൽ അസക്തിയില്ലാതെ നിങ്ങളുടെ കര്‍മ്മങ്ങൾ നിർവ്വഹിക്കുക.',
    'ദൈവത്തിന്റെ ഇഷ്ടത്തിന് കീഴടങ്ങുക, നിങ്ങളുടെ എല്ലാ പ്രവർത്തനങ്ങളും എളുപ്പമാകും.',
    'ആത്മാവിനെ തിരിച്ചറിഞ്ഞവനു കർമമില്ല.',
    'നിന്റെ ഇന്ദ്രിയങ്ങൾക്കും ആഗ്രഹങ്ങൾക്കും അടിമയാകരുത്.',
    'നിങ്ങൾ മറ്റുള്ളവരെ കൂടുതൽ സേവിക്കുമ്പോൾ, അവരുടെ ഉള്ളിലെ ആത്മാവിനെ കൂടുതൽ തിരിച്ചറിയും.',
    'എല്ലാ പ്രവർത്തനങ്ങളുടെയും സാക്ഷിയായി നിലകൊള്ളുക എന്നതാണ് പരമോന്നതമായ പ്രവർത്തനം.',
    'ചിന്തയുടെ ഫലമാണ് പ്രവർത്തി. മൗനം ആ രണ്ടിന്റെയും അഭാവമാണ്.',
    'ലോകം ഒരു നാടകവേദിയാണ്. നിങ്ങളുടെ പാത്രം നന്നായി അവതരിപ്പിക്കുക, പക്ഷേ നിങ്ങൾ ആരാണെന്ന് മറക്കരുത്.',
    'ഗുരു ഒരു വ്യക്തിയല്ല. ഗുരു ആത്മാവാണ്.',
    'ഗുരു നിങ്ങളുടെ ഉള്ളിലാണ്. ഗുരു ആന്തരിക ശബ്ദമാണ്.',
    'സത്യഗുരു ആത്‌മസാക്ഷാത്കാരത്തിലേക്ക് നയിക്കുന്നവനാണ്.',
    'ഗുരുവിന്റെ കൃപ എപ്പോഴും നിലനിൽക്കുന്നു. അതിനെ സ്വീകരിക്കുക നിങ്ങളുടെ ഉത്തരവാദിത്വമാണ്.',
    'നിന്റെ ഗുരുവിനെ ആദരിക്കുന്ന ഏറ്റവും നല്ല മാർഗം ആത്മസാക്ഷാത്കാരം നേടുക എന്നതാണ്.',
    'ഗുരു ഒരു കണ്ണാടിയാണ്, അതിൽ നിങ്ങൾക്ക് നിങ്ങളുടെ യഥാർത്ഥ ആത്മാവിനെ കാണാൻ കഴിയും.',
    'ആത്മസാക്ഷാത്കാരത്തിനായി ഗുരുകൃപ അനിവാര്യമാണ്.',
    'ഗുരു ശരീരം അല്ല. ഗുരു എല്ലാ ഹൃദയങ്ങളിലും വസിക്കുന്ന ചൈതന്യമാണ്.',
    'ഗുരു ഒരു മാർഗദർശിയാണ്, അനുഗ്രഹദാതാവല്ല.',
    'ഗുരുവിന്റെ കൃപയാണ് നിങ്ങളെ മുന്നോട്ട് കൊണ്ടുപോകുന്ന കാറ്റ്. നിങ്ങളുടെ പരിശ്രമമാണ് ആ കപ്പലിന്റെ പായം.',
    'ഗുരുവിൽ വിശ്വാസം പുലർത്തുക, ഗുരു നിങ്ങളെ സത്യത്തിലേക്ക് നയിക്കും.',
    'ഗുരു സത്യത്തിന്റെ ജീവൻമയമായ പ്രതീകമാണ്.',
    'ഗുരു നിങ്ങളിൽ നിന്ന് വേറിട്ടവനല്ല. നിങ്ങൾ ഗുരുവുമായി ഏകത്വത്തിലാണ്.',
    'ഗുരുവിന്റെ ഉപദേശം മൗനമായിരിക്കുക എന്നതാണ്.',
    'ഗുരു മനസ്സിനെ അതിജീവിക്കാൻ നിങ്ങളെ സഹായിക്കുന്നവനാണ്.',
    'മനസ്സ് എന്നത് പ്രവർത്തനത്തിലുള്ള അഹങ്കാരമാണ്.',
    'അഹങ്കാരം \'ഞാൻ ശരീരമാണ്\' എന്ന ബോധമാണ്.',
    'എഗോ മരിക്കുമ്പോൾ, ആത്മാവ് പ്രകാശിക്കുന്നു.',
    'ആത്മസാക്ഷാത്കാരത്തിന് ഏറ്റവും വലിയ തടസ്സം അഹങ്കാരമാണ്.',
    'അഹങ്കാരം ചിന്തകളുടെയും വികാരങ്ങളുടെയും ഓർമ്മകളുടെയും സമാഹാരമാണ്.',
    'മനസ്സ് ഒരു മനോഹരമായ സേവകനാണ്, പക്ഷേ അത് ഒരു അപകടകരമായ യജമാനനുമാണ്.',
    'മോക്ഷം എന്നത് മറ്റെവിടെയെങ്കിലും പോകുന്നതല്ല. അതു ഇവിടെ, ഇപ്പോൾ, ഉള്ളതിനെക്കുറിച്ചാണ്.',
    'അഹങ്കാരത്തെ നശിപ്പിക്കുന്ന ഏക മാർഗ്ഗം ആത്മനുവേണ്ടി സമർപ്പിക്കുക എന്നതാണ്.',
    'മനസ്സ് മഹത്തായ വഞ്ചകനാണ്. അത് വേറിട്ട ഒരു സ്വയംഭാവത്തിന്റെ മായാജാലം സൃഷ്ടിക്കുന്നു.',
    'അഹങ്കാരം ഭയവും ആഗ്രഹങ്ങളും കൊണ്ടു നിർമ്മിച്ച ഒരു കോട്ടയാണ്.',
    'സ്വതന്ത്രമാകുക എന്നത് മനസ്സിൽ നിന്ന് സ്വതന്ത്രമാകുക എന്നതാണ്.',
    'മനസ്സ് ഒരു കണ്ണാടിയാണ്. അതിൽ നിങ്ങൾ കാണുന്നത് നിങ്ങളുടെ സ്വന്തം ചിന്തകളുടെ പ്രതിഫലനമാണ്.',
    'മനസ്സാണ് എല്ലാ ദുഃഖത്തിനും കാരണം. ആത്മാവാണ് എല്ലാ ആനന്ദത്തിനും ഉറവിടം.',
    'എഗോ എല്ലാ പ്രശ്നങ്ങളുടെയും മൂലമാണ്. \'ഞാൻ ആഗ്രഹിക്കുന്നു\' എന്ന് പറയുന്നത് അതാണ്.',
    'മനസ്സ് ഒരു സ്വപ്ന യന്ത്രമാണ്. അത് ലോകത്തെയും അതിലെ എല്ലാ മായാജാലങ്ങളെയും സൃഷ്ടിക്കുന്നു.',
    'മനസ്സ് ഒരു നദിയാണ്. ആത്മാവ് സമുദ്രമാണ്.',
    'മോക്ഷം ഒരു ലക്ഷ്യം അല്ല, അത് ഒരു നിലയാണ്.',
    'മനസ്സ് ഒരു ഉപകരണം മാത്രമാണ്. അതിനെ ഉപയോഗിക്കുന്നത് നിങ്ങൾ തന്നെയാണ്.',
    'അഹംകാരം നമ്മൾ സ്വയം പറയുന്ന ഒരു കഥയാണ്.',
    'മനസ്സ് ഒരു തടവറയാണ്. ആത്മാവ് അതിന്റെ താക്കോലാണ്.',
    'മനസ്സ് ആത്മാവിന്റെ സൂര്യനെ മറയ്ക്കുന്ന മേഘമാണ്.',
    'അഹങ്കാരം താൽക്കാലികമായ ഒരു മായയാണ്. ആത്മാവ് ശാശ്വതമായ സത്യമാണ്.',
    'മനസ്സ് അതിഥിയാണ്. ആത്മാവാണ് ആതിഥേയൻ.',
    'മോക്ഷം സമ്പൂർണ്ണമായ ശാന്തിയും സമാധാനവും നിറഞ്ഞ ഒരു അവസ്ഥയാണ്.',
    'സ്വതന്ത്രമാകാനുള്ള ഏക മാർഗം സ്വയം ആയിരിക്കുക.',
    '\'ഞാൻ ആരാണ്?\' എന്ന ചോദ്യത്തിന് ഉത്തരം ലഭിക്കാനല്ല ഈ ചോദ്യം. ചോദ്യമുതൽ തന്നെ ഉത്തരം തന്നെയാണ്. \'ഞാൻ\' എന്ന ചിന്തയുടെ ഉറവിടം നിരന്തരം അന്വേഷിക്കുമ്പോൾ, വ്യാജ \'ഞാൻ\' അപ്രത്യക്ഷമാകുന്നു, യഥാർത്ഥ ആത്മാവ് സ്വയം പ്രകാശിക്കുന്നു.',
    'നിന്റെ ധർമ്മം \'ഇത് അല്ല, അത് അല്ല, നീ ആകുക\' എന്നതാണ്. \'ഞാൻ ആത്‌മൻ\' എന്നത് മുഴുവൻ സത്യവും ഉൾക്കൊള്ളുന്നു. \'ശാന്തനായി ഇരിക്കുക\' എന്നതാണ് മാർഗം. ശാന്തത എന്താണ് അർത്ഥമാക്കുന്നത്? അത് \'നിന്നെ നശിപ്പിക്കുക\' എന്നാണ്, കാരണം ഓരോ നാമവും രൂപവും പ്രശ്നങ്ങളുടെ കാരണമാണ്.',
    'ആത്മാവ് എപ്പോഴും അവിടെ നിലനിൽക്കുന്നു. അത് നിങ്ങൾ തന്നെയാണ്. അതിനെ നേടുകയോ തിരിച്ചറിയുകയോ ചെയ്യേണ്ട ആവശ്യമില്ല. ഒരാൾ ആത്മാവ് അല്ലെന്ന തെറ്റായ ധാരണ മാത്രം ഉപേക്ഷിക്കണം.',
    'യാത്രയോളം വ്യക്തിത്വത്തിന്റെ ആശയം നിലനിൽക്കുന്നു, ലോകവും ദൈവവും എന്ന ആശയവും നിലനിൽക്കും. വ്യക്തിത്വം അപ്രത്യക്ഷമാകുമ്പോൾ, അതിനോടൊപ്പം എല്ലാം അപ്രത്യക്ഷമാകുന്നു.',
    'സന്തോഷം നിങ്ങളുടെ സ്വഭാവമാണ്. സന്തോഷം ആഗ്രഹിക്കുന്നത് തെറ്റല്ല. തെറ്റായത് അത് അകത്താണ് എന്നിരിക്കെ പുറത്തു തേടുന്നതാണ്.',
    'മനസ്സ് ചിന്തകളുടെ കൂട്ടമാണ്. \'ഞാൻ\' എന്ന ചിന്ത അവയുടെ മൂലമാണ്. ആ മൂലം പിഴുതെറിയുമ്പോൾ, ബാക്കിയുള്ളവ എല്ലാം പിഴുതെറിയപ്പെടുന്നു.',
    'മനസ്സ് ഇല്ലാതാകുമ്പോഴാണ് ആത്മാവ് സാക്ഷാത്കരിക്കപ്പെടുന്നത്. മനസ്സ് നിലനിൽക്കുന്നിടത്തോളം സംശയവും ദുഃഖവും ഉണ്ടാകും.',
    'നിശ്ശബ്ദതയാണ് ഏറ്റവും ശക്തമായ ഉപദേശം. അതാണ് മികച്ച ഭാഷ. എല്ലാ സംശയങ്ങളും നിശ്ശബ്ദതയിൽ തീരുന്നു.',
    'ആത്മാവ് എന്നത് എത്തിപ്പിടിക്കേണ്ട ഒന്നല്ല. നിങ്ങൾ എപ്പോഴും ആത്മാവാണ്. അതിനെ എത്തിപ്പിടിക്കേണ്ടതില്ല. അവിദ്യയെ നീക്കുക മാത്രമാണ് വേണ്ടത്.',
    'മനസ്സ് അകത്തേക്ക് തിരിഞ്ഞ് അതിന്റെ സ്വഭാവത്തെ അന്വേഷിക്കുമ്പോൾ, അത് അപ്രത്യക്ഷമാവുന്നു, ശേഷിക്കുന്നത് ആത്മാവാണ്.',
    'നമ്മളെല്ലാം സത്യസ്വരൂപമായിരിക്കെ, സത്യം നേടാൻ ശ്രമിക്കുന്നത് ഇതിലേറെ വലിയൊരു രഹസ്യമില്ല.',
    'ശരീരം തന്നെ ഒരു ചിന്തയാണ്. ലോകവും ഒരു ചിന്തയാണ്. മനസ്സ് അപ്രത്യക്ഷമാകുമ്പോൾ, എല്ലാ ചിന്തകളും അപ്രത്യക്ഷമാകും.',
    'കൃപ എപ്പോഴും അവിടെ ഉണ്ട്. അത് പുതുതായി നേടേണ്ട ഒന്നല്ല. കൃപ തന്നെയാണ് ആത്മാവ്.',
    'സ്വയം സാക്ഷാത്കാരത്തിന് ഏറ്റവും വലിയ തടസ്സം അത് നേടേണ്ട ഒന്നാണെന്ന ആശയമാണ്.',
    'സ്വയം തിരിച്ചറിയാൻ ശ്രമിക്കേണ്ടതില്ല. അതിനെ തിരിച്ചറിയുന്നതിൽ നിന്നുള്ള തടസ്സങ്ങൾ നീക്കാൻ മാത്രം ശ്രമിക്കുക.',
    'മനസ്സ് മനസ്സിനെ നശിപ്പിക്കാൻ കഴിയില്ല. മനസ്സ് അകത്തേക്ക് തിരിഞ്ഞ് അതിന്റെ ഉറവിടത്തിൽ ലയിക്കുമ്പോഴാണ് അത് മരിക്കുന്നത്.',
    'സ്വയം അന്വേഷണം \'ഞാൻ ആരാണ്?\' എന്ന മന്ത്രം ആവർത്തിക്കുന്നത് അല്ല. \'ഞാൻ\' എന്ന അനുഭവത്തിൽ ശ്രദ്ധ കേന്ദ്രീകരിച്ച് അതിന്റെ ഉറവിടം കണ്ടെത്തുന്നതുവരെ തുടരുക എന്നതാണ്.',
    'അഹംഭാവം ഒരു നിഴലാണ് മാത്രം. നിങ്ങൾ അതിനെ അന്വേഷിക്കുമ്പോൾ, അത് അപ്രത്യക്ഷമാകുന്നു.',
    'എഗോ അപ്രത്യക്ഷമാകുമ്പോൾ ശേഷിക്കുന്നത് ആത്‌മയാണ്, അത് ആനന്ദമാണ്.',
    'അറിവിന്റെ പ്രാപ്തി എന്നൊന്നില്ല. അവിദ്യയെ നഷ്ടപ്പെടുത്തലാണ് മാത്രം.',
    'ആത്മാവ് എപ്പോഴും സന്നിഹിതമാണ്. തടസ്സം ചഞ്ചലമായ മനസ്സാണ്.',
    'ശാന്തമായി നിലകൊള്ളുക എന്നതാണ് ജ്ഞാനദർശനം.',
    'നീ എന്ത് ചെയ്താലും, \'ഞാൻ\' എന്നത് അന്വേഷിക്കപ്പെടണം. അതാണ് ഏകമാർഗ്ഗം.',
    'നിങ്ങൾ ചിന്തകളില്ലാതെ ആത്മാവായി നിലനിൽക്കാൻ കഴിയുമെങ്കിൽ, എല്ലാ പ്രശ്നങ്ങളും സ്വാഭാവികമായി ലയിച്ചുപോകുന്നതായി നിങ്ങൾ കണ്ടെത്തും.',
    '\'ഞാൻ\' എന്ന ബോധം ശരീരത്തിൽ ഉദിക്കുന്നു, എന്നാൽ അത് ശരീരത്തിന് സ്വന്തമല്ല.',
    'പുറത്തേക്ക് തിരിയുന്ന മനസ്സ് ചിന്തകളും വസ്തുക്കളും സൃഷ്ടിക്കുന്നു. അകത്തേക്ക് തിരിയുന്ന മനസ്സ് ആത്മാവായി മാറുന്നു.',
    'ലോകം നിങ്ങളുടെ പുറത്തല്ല. ലോകം മനസ്സിന്റെ പ്രതിഫലനം മാത്രമാണ്.',
    'മനസ്സ് ശാന്തമായാൽ ലോകവും ശാന്തമായി തോന്നും.',
    'ആവശ്യമുള്ളത് മനസ്സിനെ നിയന്ത്രിക്കുക അല്ല, മറിച്ച് അതിന്റെ സ്വഭാവത്തെ അന്വേഷിക്കുക എന്നതാണ്.',
    'ഒരാൾ \'ഞാൻ ശരീരമാണ്\' എന്ന് കരുതുന്നിടത്തോളം കാലം, ദുഃഖത്തിൽ നിന്ന് രക്ഷപ്പെടാനാകില്ല.',
    'ബുദ്ധിയാൽ ആത്മാവിനെ അറിയാൻ കഴിയില്ല. ബുദ്ധി ശമിക്കുമ്പോൾ അത് സ്വയം വെളിപ്പെടുന്നു.',
    '\'ഞാൻ\' എന്ന ചിന്ത അവസാനിക്കുമ്പോൾ, ആത്മാവ് മാത്രം നിലനിൽക്കും.',
    '\'ഞാൻ\'-എന്ന ചിന്ത ഒരു കള്ളൻ പോലീസുകാരനായി നടിക്കുന്നതുപോലെയാണ്.',
    'ആത്മാവ് വരുകയും പോകുകയും ചെയ്യുന്നില്ല. ചിന്തകൾ മാത്രമാണ് വരുകയും പോകുകയും ചെയ്യുന്നത്.',
    'ബോധ്യത്തിന്റെ അവസ്ഥ സ്വാഭാവികമായ അവസ്ഥയാണ്.',
    'നിങ്ങൾ ലോകത്തെ ത്യജിക്കേണ്ടതില്ല. ലോകത്തെ വേർതിരിച്ചുനോക്കുന്ന അഹങ്കാരത്തെ ത്യജിക്കുക.',
    'ശരീരവും മനസ്സും ഉപകരണങ്ങളാണ്. നിങ്ങൾ അവയല്ല.',
    'സ്വാതന്ത്ര്യം പുറത്തു കണ്ടെത്താനാകില്ല. സ്വാതന്ത്ര്യം കള്ള \'ഞാൻ\' എന്നതിൽ നിന്നാണ്.',
    'ആത്മാവ് ഒരു വസ്തുവായി അനുഭവപ്പെടുന്നതല്ല. അത് അനുഭവിക്കുന്നവനാണ്.',
    'ചോദ്യം മൗനത്തിലേക്ക് നയിക്കുന്നു, മൗനം സത്യത്തെ വെളിപ്പെടുത്തുന്നു.',
    'വസ്തുക്കളോട് ആസക്തിയുള്ള മനസ്സ് ബന്ധിതമാണ്. അസക്തമായ മനസ്സ് സ്വതന്ത്രമാണ്.',
    'ശ്രമവും കൃപയും തമ്മിൽ വ്യത്യാസമില്ല.',
    'നിങ്ങൾ പൂർണ്ണമായി സമർപ്പിച്ചാൽ, ചോദ്യങ്ങൾ ചോദിക്കാൻ ആരും ബാക്കിയുണ്ടാകില്ല.',
    'തന്നെ അന്വേഷിക്കുന്നതാണു് ഏറ്റവും ഉത്തമമായ ശിക്ഷണം.',
    'ആത്മാവേ സത്യമാണ്. ബാക്കി എല്ലാം മായയാണ്.',
    'അഹംകാരം വസ്തുക്കളുമായി ഐക്യപ്പെടുന്നതിലൂടെ ജീവിക്കുന്നു. ഐക്യപ്പെടൽ അവസാനിക്കുമ്പോൾ, അഹംകാരം നശിക്കുന്നു.',
    'ആത്മാവ് അകത്തോ പുറത്തോ അല്ല. അത് മാത്രമാണ്.',
    'ജനിച്ചവയ്ക്ക് മരണം അനിവാര്യമാണ്. യഥാർത്ഥമായത് ജനിക്കുകയില്ല.',
    'ആത്മാവായി നിലകൊള്ളുക എന്നത് ധ്യാനത്തിന്റെ ഉന്നത രൂപമാണ്.',
    '\'ഞാൻ ആരാണ്?\' എന്ന് ചോദിക്കുന്നത് മനസ്സിനെ അകത്തേക്ക് തിരിക്കാൻ സഹായിക്കുന്നു.',
    'കർത്തൃത്വബോധമാണ് ബന്ധനത്തിന്റെ കാരണം.',
    'നീ ചെയ്യുന്നതല്ലെന്ന് തിരിച്ചറിയുമ്പോൾ, പ്രവർത്തികൾ തുടരുന്നു, പക്ഷേ ബന്ധനങ്ങളില്ലാതെ.',
    'ശാന്തി നിങ്ങളുടെ യഥാർത്ഥ സ്വഭാവമാണ്.',
    'ആസക്തിയില്ലായ്മയാണ് ജ്ഞാനം.',
    'ആത്മാവിന് സംരക്ഷണം ആവശ്യമില്ല.',
    'ദുഃഖം താൽക്കാലികമായതുമായി ഐക്യപ്പെടുന്നതിൽ നിന്നാണ് ഉദ്ഭവിക്കുന്നത്.',
    'ആത്മാവ് ജാഗ്രത്, സ്വപ്ന, സുഷുപ്തി അവസ്ഥകളുടെ സാക്ഷിയാണ്.',
    'നിദ്ര ആനന്ദകരമാണ്, കാരണം അഹം ഇല്ലാതിരിക്കുന്നു.',
    'സ്ഥിരമായത് നഷ്ടപ്പെടുകയില്ല.',
    'സന്തോഷം പുറത്തു തേടുന്ന മനസ്സ് അതിനെ ഒരിക്കലും കണ്ടെത്തുകയില്ല.',
    'യാഥാർത്ഥ്യം ലളിതമാണ്. മനസ്സ് അതിനെ സങ്കീർണ്ണമാക്കുന്നു.',
    'തിരയുന്നവൻ തന്നെ തേടപ്പെടുന്നത്.',
    'അഹങ്കാരത്തോടൊപ്പം ഇല്ലാതെ അജ്ഞാനം എന്നത് ഒന്നുമില്ല.',
    'എഗോ മരിച്ചാൽ, ആത്മാവ് പ്രകാശിക്കുന്നു.',
    'മനസ്സ് ആത്മാവിൽ നിന്ന് ഒരു ചലനം മാത്രം അകലെ.',
    'ശാന്തനായി, നീ ആത്മാവാണെന്ന് അറിയുക.',
    'ആത്മാവ് സ്വയം പ്രകാശിക്കുന്നതാണ്.',
    'ചോദ്യം അജ്ഞതയെ നശിപ്പിക്കുന്നു.',
    'ആത്മാവ് ശരീരത്തിന് സംഭവിക്കുന്നതുകൊണ്ട് ബാധിക്കപ്പെടുന്നില്ല.',
    'മോക്ഷം ഭാവിയിൽ ഉള്ള ഒന്നല്ല. അത് ഇപ്പോഴാണ്.',
    'അഹങ്കാരം ബന്ധനമാണ് സൃഷ്ടിക്കുന്നത്; ആത്മാവ് സ്വാതന്ത്ര്യമാണ്.',
    'മനസ്സ് ആത്മാവിൽ വിശ്രമിക്കുമ്പോൾ, അതാണ് യഥാർത്ഥ സന്ന്യാസം.',
    'സ്വയം മാത്രമാണ് യാഥാർത്ഥ്യം; അഹം യാഥാർത്ഥ്യമല്ല.',
    '\'ഞാൻ ശരീരമാണ്\' എന്ന ധാരണയാണ് ആദിമമായ അജ്ഞാനം.',
    'എല്ലാം നിഷേധിക്കപ്പെട്ടപ്പോൾ ആത്മാവ് മാത്രം നിലനിൽക്കും.',
    'ധ്യാനം എന്നത് ആത്മാവായി നിലനിൽക്കുന്നതാണ്.',
    'ഹൃദയം ശാരീരികമായ ഒരു സ്ഥലം അല്ല; അത് ചൈതന്യത്തിന്റെ ഉറവിടമാണ്.',
    'എല്ലാ ആചാരങ്ങളും മനസ്സിനെ ശാന്തമാക്കാനാണ്.',
    'യഥാർത്ഥ ജ്ഞാനം മൗനമാണ്.',
    'ആത്മാവ് എപ്പോഴും സാക്ഷാത്കൃതമാണ്.',
    'നീ ബന്ധിതനല്ല; നീ ബന്ധിതനാണെന്ന് കരുതുന്നു.',
    '\'ഞാൻ\' മാഞ്ഞുപോകുമ്പോൾ, ആത്മാവ് ഉദിക്കുന്നു.',
    'ആത്മാവു മാത്രമേ നിലനിൽക്കൂ, മറ്റൊന്നുമില്ല.',
    'മാറ്റം ഒന്നുമില്ല. ഉള്ളത് മാത്രം ഉള്ളത്.',
    'ആത്മാവ് കാലത്തിന്റെ അതീതമാണ്.',
    'ആത്മാവിനെ അറിയുക എന്നത് ആത്മാവായി നിലകൊള്ളുന്നതാണ്.',
    'ആത്മാവ് ശുദ്ധമായ ബോധമാണ്.',
    'ആത്മാവിൽ ലയിച്ച മനസ്സ് വീണ്ടും ഉയരുകയില്ല.',
    'അന്വേഷണമാത്രം നേരായ മാർഗമാണ്.',
    'അഹംകാരമാണ് ആത്മാവിനും ശരീരത്തിനും ഇടയിലുള്ള കെട്ട്.',
    'സ്വാതന്ത്ര്യം എന്നത് അഹങ്കാരത്തിൽ നിന്ന് മോചിതമാകുന്നതാണ്.',
    'മനസ്സ് ശമിക്കുമ്പോൾ സമാധാനം വാഴുന്നു.',
    'ആത്മാവ് അറിഞ്ഞിരിക്കേണ്ട ഒന്നല്ല, അനുഭവിക്കേണ്ട ഒന്നാണ്.',
    'ആത്മാവ് എപ്പോഴും സിദ്ധമാണ്.',
    'അഹങ്കാരത്തിന്റെ ഇല്ലായ്മ ആത്മസാക്ഷാത്കാരമാണ്.',
    'നിനക്കുള്ളവനായി നിലകൊള്ളുക.',
    'അസ്തിത്വം ഏറ്റവും ഉന്നതമായ ഉപദേശമാണ്.',
    'ആത്മാവ് എല്ലായിടത്തും ഒരേപോലെയാണ്.',
    'സത്യമാണ്, നിങ്ങൾ ഇതിനകം സ്വതന്ത്രരാണ്.',
    'ആത്മാവിൽ നിലകൊള്ളുക, എല്ലാം ശുഭമാകും.',
  ],

  [
    Article(
        heading: 'മഹർഷി രാമണന്റെ ഉപദേശങ്ങൾ',
        body: 'സന്തോഷം\n\nഎല്ലാ ജീവികളുടെയും ആഗ്രഹം എപ്പോഴും സന്തോഷമാണ്, ദുഖത്തിന്റെ ഒരു നിഴലുമില്ലാത്ത സന്തോഷം. ഒരേസമയം, എല്ലാവരും സ്വയം ഏറ്റവും അധികം സ്നേഹിക്കുന്നു. സ്നേഹത്തിന്റെ കാരണം മാത്രം സന്തോഷമാണ്. അതിനാൽ, ആ സന്തോഷം ഒരാളിൽ തന്നെ നിക്ഷിപ്തമായിരിക്കണം. കൂടാതെ, ആ സന്തോഷം എല്ലാവരും ഉറക്കത്തിൽ അനുഭവിക്കുന്നു, മനസില്ലാത്തപ്പോൾ. ആ സ്വാഭാവിക സന്തോഷത്തെ നേടാൻ, ഒരാളെ അറിയണം. അതിന്, ആത്മാവിന്റെ അന്വേഷനം, \'ഞാൻ ആരാണ്?\' പ്രധാന മാർഗമാണ്.\n\nചേതന\n\nഅസ്തിത്വം അല്ലെങ്കിൽ ചേതന മാത്രമാണ് യഥാർത്ഥത. ചേതനയും ഉണർവും ചേർന്നാൽ, നാം ഉണർവെന്ന് വിളിക്കുന്നു. ചേതനയും ഉറക്കവും ചേർന്നാൽ, നാം ഉറക്കമെന്ന് വിളിക്കുന്നു. ചേതനയും സ്വപ്നവും ചേർന്നാൽ, നാം സ്വപ്നം എന്ന് വിളിക്കുന്നു. എല്ലാ ചിത്രങ്ങൾ വരുകയും പോകുകയും ചെയ്യുന്ന സ്ക്രീൻ ആണ് ചേതന. സ്ക്രീൻ യാഥാർത്ഥ്യമാണു, ചിത്രങ്ങൾ അതിൽ വെറും നിഴലുകളാണ്. \n\nമനസ്സ് \n\nമനസ്സ് ആത്മാവിൽ നിക്ഷിപ്തമായ ഒരു അത്ഭുതശക്തിയാണ്. \n\nഈ ശരീരത്തിൽ ‘ഞാൻ’ എന്ന രൂപത്തിൽ ഉത്ഭവിക്കുന്നതു മനസ്സാണ്. \n\nസൂക്ഷ്മമായ മനസ്സ് മസ്തിഷ്കത്തിലൂടെയും ഇന്ദ്രിയങ്ങളിലൂടെയും ഉയർന്നപ്പോൾ, ഭൗതികമായ പേരുകളും രൂപങ്ങളും തിരിച്ചറിഞ്ഞു. ഹൃദയത്തിൽ നിലനിൽക്കുമ്പോൾ പേരുകളും രൂപങ്ങളും ഇല്ലാതാകുന്നു... മനസ്സ് ഹൃദയത്തിൽ നിലനിൽക്കുമ്പോൾ, എല്ലാ ചിന്തകളുടെ ഉറവിടമായ ‘ഞാൻ’ അല്ലെങ്കിൽ എഗോ ഇല്ലാതാകും, മാത്രമല്ല, സത്യമായ, നിത്യമായ ‘ഞാൻ’ മാത്രം പ്രകാശിക്കും. എവിടെ എഗോയുടെ ഏറ്റവും ചെറിയ അടയാളവും ഇല്ല, അവിടെ ആത്മാവാണ്. \n\n“ഞാൻ ആരാണ്?” – അന്വേഷണമെന്നു \n\nഎല്ലാ ചിന്തകൾക്കും ഉറവിടം ‘ഞാൻ’ ചിന്തയാണ്. \n\n‘ഞാൻ ആരാണ്?’ എന്ന ആത്മാന്വേഷണത്തിലൂടെ മാത്രമാണ് മനസ്സ് ലയിക്കുന്നത്. ‘ഞാൻ ആരാണ്?’ എന്ന ചിന്ത എല്ലാ മറ്റ് ചിന്തകളെയും നശിപ്പിക്കും, ഒടുവിൽ അതിനെ തന്നെ കൊല്ലും. മറ്റു ചിന്തകൾ ഉയർന്നാൽ, അവയെ പൂർത്തിയാക്കാൻ ശ്രമിക്കാതെ, ഈ ചിന്ത ആരുടെ ചിന്തയാണ് എന്ന് അന്വേഷിക്കണം. എത്ര ചിന്തകൾ ഉയർന്നാലും അതെന്ത് പ്രാധാന്യം? ഓരോ ചിന്തയും ഉയർന്നപ്പോൾ, ശ്രദ്ധയോടെ ആ ചിന്ത ആരുടെ ചിന്തയാണ് എന്ന് ചോദിക്കണം. ഉത്തരം \'എനിക്ക്\' ആയിരിക്കും. \'ഞാൻ ആരാണ്?\' എന്ന് ചോദിച്ചാൽ, മനസ്സ് അതിന്റെ ഉറവിടത്തിലേക്ക് (അല്ലെങ്കിൽ അത് എവിടെ നിന്നാണ് വന്നത്) തിരികെ പോകും. ഉയർന്ന ചിന്തയും മുങ്ങും. ഇങ്ങനെ കൂടുതൽ പ്രാക്ടീസ് ചെയ്യുമ്പോൾ, മനസ്സിന്റെ ഉറവിടത്തിൽ നിലനിൽക്കാനുള്ള ശക്തി വർദ്ധിക്കുന്നു.\n\nസർവസ്വം സമർപ്പിക്കുക\n\nസർവസ്വം സമർപ്പിക്കാൻ രണ്ട് വഴികളുണ്ട്. ഒന്നാണ് \'ഞാൻ\' എന്നതിന്റെ ഉറവിടത്തിലേക്ക് നോക്കുകയും ആ ഉറവിടത്തിൽ ലയിക്കുകയും ചെയ്യുക. മറ്റൊന്ന് \'ഞാൻ തന്നെ അശക്തനാണ്, ദൈവം മാത്രമാണ് ശക്തമായവൻ, എനിക്ക് സുരക്ഷിതത്വം നേടാൻ മറ്റൊരു മാർഗമില്ല\' എന്ന അനുഭവം ആണ്, അതിനാൽ ദൈവം മാത്രം ഉണ്ട് എന്ന വിശ്വാസം നാം ക്രമമായി വികസിപ്പിക്കുന്നു, എഗോയെ അവഗണിക്കുന്നു. ഈ രണ്ട് മാർഗങ്ങളും ഒരേ ലക്ഷ്യത്തിലേക്ക് നയിക്കുന്നു. സമ്പൂർണ്ണ സമർപ്പണം ജ്ഞാനത്തിന്റെ അല്ലെങ്കിൽ മോക്ഷത്തിന്റെ മറ്റൊരു പേരാണ്.\n\nമൂന്ന് അവസ്ഥകൾ: ജാഗ്രത, സ്വപ്നം, ഉറക്കം\n\nസ്വപ്നവും ജാഗ്രതാവസ്ഥയും തമ്മിൽ വ്യത്യാസമില്ല, സ്വപ്നം ചെറുതാണ്, ജാഗ്രത ദീർഘമാണ്. ഇരുവരും മനസ്സിന്റെ ഫലമാണ്. നമ്മുടെ യാഥാർത്ഥ്യാവസ്ഥ ജാഗ്രത, സ്വപ്നം, ഉറക്കാവസ്ഥകളെ മറികടന്ന്, തുരിയ എന്നറിയപ്പെടുന്നു.\n\nശ്രീ രാമന മഹർഷി - കൃപയും ഗുരുവും\n\nഞാൻ ഗുരു ആവശ്യമില്ല എന്ന് പറഞ്ഞിട്ടില്ല. എന്നാൽ, ഒരു ഗുരു എപ്പോഴും മനുഷ്യരൂപത്തിൽ ഉണ്ടാവേണ്ടതില്ല. ആദ്യം ഒരു വ്യക്തി തന്റെ തനിക്കു താഴ്ന്നവനാണെന്ന് കരുതുന്നു, അതിനാൽ തന്നെ ഒരു ഉന്നത, എല്ലാം അറിയുന്ന, എല്ലാം ശക്തിയുള്ള ദൈവം തന്റെയും ലോകത്തിന്റെ വിധിയെ നിയന്ത്രിക്കുന്നു എന്ന് വിശ്വസിക്കുന്നു, അവനെ ആരാധിക്കുന്നു അല്ലെങ്കിൽ ഭക്തി ചെയ്യുന്നു. അദ്ദേഹം ഒരു പ്രത്യേക ഘട്ടത്തിൽ എത്തുമ്പോൾ, ജ്ഞാനത്തിന് യോഗ്യനായപ്പോൾ, അദ്ദേഹം ആരാധിച്ച ദൈവം ഗുരുവായി വരുന്നു, അവനെ മുന്നോട്ടു നയിക്കുന്നു. ആ ഗുരു അദ്ദേഹത്തെ അറിയിക്കാൻ മാത്രം വരുന്നു, \'ആ ദൈവം നിന്റെ ഉള്ളിൽ ആണ്. ഉള്ളിലേക്ക് മുങ്ങി തിരിച്ചറിയുക.\' ദൈവം, ഗുരു, ആത്മാവ് എല്ലാം ഒരേ ആണ്.\n\nആത്മാ-തത്ത്വം\n\nനാം തിരിച്ചറിയൽ എന്ന് വിളിക്കുന്ന അവസ്ഥ, സ്വയം ആയിരിക്കുകയാണ്, ഒന്നും അറിയാതെ അല്ലെങ്കിൽ ഒന്നും ആകാതെ. ആരെങ്കിലും തിരിച്ചറിഞ്ഞാൽ, അവൻ മാത്രം ഉള്ളത് ആണ്, എന്നും ഉണ്ടായത് ആണ്. ആ അവസ്ഥയെ അദ്ദേഹം വിവരണം ചെയ്യാൻ കഴിയില്ല. അദ്ദേഹം ആത്മാവായി മാത്രം ഇരിക്കണം. നല്ല പദം ഇല്ലാത്തതിനാൽ, സ്വയം തിരിച്ചറിയൽ എന്ന് നാം അപ്രകൃതമായി സംസാരിക്കുന്നു.\n\n\'ഉള്ളത്\' സമാധാനമാണ്. നാം ചെയ്യേണ്ടത് ശാന്തമായിരിക്കുകയാണ്. സമാധാനം നമ്മുടെ യഥാർത്ഥ സ്വഭാവമാണ്. നാം അതിനെ നശിപ്പിക്കുന്നു. നാം അതിനെ നശിപ്പിക്കുന്നത് നിർത്തേണ്ടതാണ്.\n\nഹൃദയം\n\nഹൃദയത്തിന്റെ ആഴത്തിൽ, ഏക ബ്രഹ്മൻ \'ഞാൻ\'-\'ഞാൻ\' എന്ന അനുഭവത്തിൽ ആത്മനായി (ആത്മ) സ്വയം പ്രകാശിക്കുന്നു. നിങ്ങളുടെ ഉള്ളിലേക്ക് മുങ്ങി ഹൃദയത്തെ എത്തുക, ശ്വാസം നിയന്ത്രിച്ച് അല്ലെങ്കിൽ ആത്മാവിന്റെ അന്വേഷനത്തിൽ ചിന്ത കേന്ദ്രീകരിച്ച്. ഇങ്ങനെ നിങ്ങൾ ആത്മയിൽ സ്ഥിരമായി നിൽക്കും.\n\nവിരമനം\n\n‘മോക്ഷ (മുക്തി)യുടെ പദ്ധതിയിൽ ഒരു ഗൃഹസ്ഥൻ എങ്ങനെ മുന്നേറുന്നു?’ എന്ന് ചോദിച്ചപ്പോൾ, ഭഗവാൻ പറഞ്ഞു, ‘നിങ്ങൾ ഗൃഹസ്ഥൻ ആണെന്ന് നിങ്ങൾക്ക് എന്തുകൊണ്ട് തോന്നുന്നു? നിങ്ങൾ സന്യാസിയായി (തപസ്വി) പുറത്ത് പോകുകയാണെങ്കിൽ, നിങ്ങൾ സന്യാസിയാണെന്ന് തോന്നുന്ന സമാനമായ ചിന്ത നിങ്ങൾക്കു പിന്തുടരുന്നുണ്ടാകും. നിങ്ങൾ ഗൃഹത്തിൽ തുടരുകയോ അതിനെ വിട്ട് കാടിലേക്ക് പോകുകയോ ചെയ്താലും, നിങ്ങളുടെ മനസ്സ് നിങ്ങളോടൊപ്പം പോകുന്നു. ആത്മാവ് എല്ലാ ചിന്തകളുടെയും ഉറവിടമാണ്. ഇത് ശരീരവും ലോകവും സൃഷ്ടിക്കുന്നു, നിങ്ങളെ grihastha ആണെന്ന് കരുതാൻ നിർബന്ധിതമാക്കുന്നു. നിങ്ങൾ ലോകത്തെ വിട്ടുവീഴ്ച ചെയ്യുകയാണെങ്കിൽ, അത് grihastha യുടെ ചിന്തയ്ക്ക് sanyasi യുടെ ചിന്തയെ മാത്രം മാറ്റിസ്ഥാപിക്കും, കൂടാതെ കാടിന്റെ പരിസരങ്ങൾ വീട്ടിലെവിടെയോ ഉള്ളവയെക്കാൾ മാറ്റും. എന്നാൽ മാനസിക തടസ്സങ്ങൾ അവിടെ തന്നെ ഉണ്ടാകും. പുതിയ പരിസരങ്ങളിൽ അവ കൂടുതൽ വർദ്ധിക്കും. പരിസരം മാറുന്നതിൽ സഹായം ഇല്ല. തടസ്സം മനസ്സിലാണ്. ഇത് വീട്ടിലോ കാടിലോ മറികടക്കണം. നിങ്ങൾ കാടിൽ അത് ചെയ്യാൻ കഴിയുന്നെങ്കിൽ, വീട്ടിൽ എന്തുകൊണ്ട് കഴിയില്ല? അതിനാൽ, നിങ്ങളുടെ പരിസരം എന്തുകൊണ്ട് മാറ്റണം? നിങ്ങൾ ഇപ്പോൾ എവിടെയായാലും, നിങ്ങളുടെ ശ്രമങ്ങൾ നടത്താൻ കഴിയും. നിങ്ങളുടെ ഇച്ഛയ്ക്കനുസരിച്ച് പരിസരം ഒരിക്കലും മാറില്ല.\n\nഭാഗ്യവും സ്വാതന്ത്ര്യവും\n\nസ്വാതന്ത്ര്യവും വിധിയും എപ്പോഴും നിലനിൽക്കുന്നു. ഭാഗ്യം കഴിഞ്ഞ ക്രിയയുടെ ഫലമാണ്; ഇത് ശരീരത്തെ സംബന്ധിക്കുന്നു. ശരീരം അതിന് അനുയോജ്യമായ രീതിയിൽ പ്രവർത്തിക്കട്ടെ. നിങ്ങൾ അതിനെക്കുറിച്ച് എന്തുകൊണ്ടാണ് ആശങ്കപ്പെടുന്നത്? നിങ്ങൾ അതിന് എന്തുകൊണ്ടാണ് ശ്രദ്ധ നൽകുന്നത്? സ്വാതന്ത്ര്യവും ഭാഗ്യവും ശരീരം നിലനിൽക്കുന്നതുവരെ നിലനിൽക്കുന്നു. എന്നാൽ ജ്ഞാനം ഇരുവരെയും അതിജീവിക്കുന്നു. ആത്മാവ് അറിവും അജ്ഞാനവും അതീതമാണ്. എന്തെങ്കിലും സംഭവിക്കുമ്പോൾ, അത് ഒരാളുടെ കഴിഞ്ഞ പ്രവർത്തനങ്ങളുടെ ഫലമായി, ദിവ്യ ഇച്ഛയും മറ്റ് ഘടകങ്ങളും മൂലമാണ്.\n\nഭാഗ്യത്തെ കീഴടക്കാൻ അല്ലെങ്കിൽ അതിൽ നിന്ന് സ്വതന്ത്രമായിരിക്കാൻ രണ്ട് വഴികൾ മാത്രമേ ഉണ്ടാകൂ. ഒരു വ്യക്തി ഈ വിധിയെന്തിന് എന്നറിയാൻ ശ്രമിക്കണം, അതും മനസ്സിലാക്കണം, വിധിയാൽ ബദ്ധമായത് എഗോ മാത്രമാണ്, ആത്മാവ് അല്ല, എഗോ ഇല്ലാതായതാണ്. \n\nമറ്റൊരു മാർഗം എഗോ നശിപ്പിക്കുക എന്നതാണ്, അതിന് കർത്താവിന് സമർപ്പണം ചെയ്യണം, തന്റെ അശക്തി തിരിച്ചറിഞ്ഞ് എല്ലായ്പ്പോഴും \'ഞാൻ അല്ല, നീയാണേ കർത്താവേ\' എന്ന് പറയണം, \'ഞാൻ\' എന്നുള്ള എല്ലാ ബോധവും \'എന്റെ\' എന്നുള്ള ബോധവും വിട്ടുകൊടുക്കണം, കർത്താവിന് താൻ ഇഷ്ടപ്പെടുന്ന രീതിയിൽ നിങ്ങളെ ചെയ്യാൻ വിട്ടുകൊടുക്കണം. എഗോയുടെ പൂർണ്ണമായ മായ്ച്ച് വിധിയെ ജയിക്കാൻ ആവശ്യമാണ്, നിങ്ങൾ ഈ മായ്ച്ച് സ്വയം അന്വേഷിക്കുന്നതിലൂടെ അല്ലെങ്കിൽ ഭക്തി മാർഗത്തിലൂടെ നേടുന്നുവെങ്കിൽ. \n\nജ്ഞാനി \n\nഒരു ജ്ഞാനി ജീവിച്ചിരിക്കുമ്പോൾ തന്നെ, ഇവിടെ, ഇപ്പോൾ മോക്ഷം നേടിയിട്ടുണ്ട്. അവൻ ശരീരം വിട്ടുപോകുന്നത് എങ്ങനെ, എവിടെ, എപ്പോഴാണ് എന്നതിൽ അവനേക്കാൾ പ്രാധാന്യമില്ല. ചില ജ്ഞാനികൾ ദുരിതം അനുഭവിക്കുന്നതായി തോന്നാം, മറ്റുള്ളവർ സമാധിയിൽ ആയിരിക്കാം; മറ്റുള്ളവർ മരണത്തിന് മുമ്പ് കാഴ്ചയിൽ നിന്ന് അപ്രത്യക്ഷമാകാം. എന്നാൽ, ഇതു അവരുടെ ജ്ഞാനത്തിന് മാറ്റമുണ്ടാക്കുന്നില്ല. ആ ദുരിതം ദൃശ്യമാണ്, കാണുന്നവനിൽ യാഥാർത്ഥ്യമെന്നു തോന്നാം, എന്നാൽ ജ്ഞാനിക്ക് അത് അനുഭവപ്പെടുന്നില്ല, കാരണം അദ്ദേഹം ശരീരത്തിനൊപ്പം ആത്മാവിന്റെ തെറ്റായ തിരിച്ചറിവിനെ അതിജീവിച്ചിരിക്കുന്നു.\n\nജ്ഞാനി തന്റെ ശരീരം ആണെന്നു കരുതുന്നില്ല. അദ്ദേഹം ശരീരത്തെ പോലും കാണുന്നില്ല. അദ്ദേഹം ശരീരത്തിൽ വെച്ച് മാത്രം ആത്മാവിനെ കാണുന്നു. ശരീരം ഇല്ലെങ്കിൽ, എന്നാൽ വെറും ആത്മാവാണെങ്കിൽ, അതിന്റെ ഏതെങ്കിലും രൂപത്തിൽ അപ്രത്യക്ഷമാകുന്നതിന്റെ ചോദ്യമുണ്ടാവുന്നില്ല.\n\nശ്രീ രാമന മഹർഷി, കുരങ്ങിന്റെ പ്രാക്ടീസ്, സമർപ്പണം, ഭക്തി\n\nശ്രീ രാമന മഹർഷിയുടെ ജീവിതവും ഉപദേശങ്ങളും പ്രകാശത്തിൽ, അരുണാചല ആശ്രമത്തിലെ ഭക്തർ ആത്മീയ പ്രാക്ടീസ് (സാധന) അനിവാര്യമാണ് എന്ന വിശ്വാസത്തിലാണ്. ശാന്തി, ആനന്ദം, അമരത്വം എന്നിവ ധ്യാനവും ആത്മാവിവേചനവും ഭക്തിയും അഭ്യസിക്കുന്ന ആസക്തരായവർക്കു ലഭ്യമാണ്. ഗുരുവിന്റെ അനുഗ്രഹം എപ്പോഴും സാന്നിധ്യത്തിൽ ഉണ്ട്, എന്നാൽ ഈ അനുഗ്രഹം അവരുടെ ജീവിതം ഉപദേശങ്ങളുടെ അഭ്യസനത്തിലേക്ക് സമർപ്പിക്കുന്ന കുറച്ച് സത്യസന്ധമായ സാധകന്മാർക്കു മാത്രമാണ് പൂർണ്ണമായും അനുഭവപ്പെടുന്നത്.\n\nശ്രീ രാമണ മഹർഷി തന്റെ കാലത്തിനായി മാത്രം ജീവിച്ചിരുന്നില്ലെന്ന് ഞങ്ങൾ വിശ്വസിക്കുന്നു. അദ്ദേഹം ശാരീരികമായി സാന്നിധ്യത്തിൽ ഉണ്ടായപ്പോൾ പോലെ, ഇപ്പോഴും അദ്ദേഹത്തിന്റെ സാന്നിധ്യവും മാർഗനിർദ്ദേശവും അനുഭവിക്കാം. സത്യസന്ധമായ ആസക്തിയും ആഗ്രഹവും കൊണ്ട് അദ്ദേഹത്തെ തിരിഞ്ഞു നോക്കുന്നവർ, അദ്ദേഹത്തിന്റെ ഉപദേശങ്ങൾ പ്രയോഗിക്കാൻ ശ്രമിക്കുന്നവർ, അദ്ദേഹത്തിന്റെ അനുഗ്രഹവും മാർഗനിർദ്ദേശവും അനുഭവിക്കും. ഇതിൽ സംശയമില്ല.\n\nഅരുണാചല ആശ്രമത്തിൽ, ഭഗവാൻ ശ്രീ രാമണ മഹർഷി അധ്യാപകനും ഗുരുവും ആയി തുടരുന്നു. ശ്രദ്ധയുള്ളവന്റെ ജീവിതത്തിൽ പ്രഭാഷണങ്ങളും ചർച്ചകളും ഒരു സ്ഥാനം ഉണ്ടാകും, എന്നാൽ അരുണാചല ആശ്രമം സന്ദർശകരുടെയും വാസികളുടെയും ഹൃദയത്തിൽ ശ്രീ രാമന മഹർഷിയുടെ ഉപദേശങ്ങൾ നിശബ്ദതയിലൂടെ ആസ്വദിക്കാൻ അനുവദിക്കുന്ന രീതിയിൽ പരിപാലിക്കപ്പെടുന്നു. അദ്ദേഹത്തിന്റെ ഉപദേശങ്ങൾ എപ്പോഴും നിശബ്ദതയിൽ പ്രചരിക്കുന്നു, അവയെ കേൾക്കാൻ നാം നമ്മുടെ മനസ്സിനെ നിശബ്ദമാക്കേണ്ടതുണ്ട്. പ്രഭാഷണങ്ങളും ചർച്ചകളും അദ്ദേഹത്തിന്റെ ഹൃദയത്തിലെ നിശബ്ദ ഉപദേശത്തെ മറയ്ക്കാൻ കഴിയും.\n\n“നിശബ്ദത എല്ലാ മതങ്ങളുടെ നദികൾ ഒഴുകുന്ന സമുദ്രമാണ്.” \n\n— തയുമാനവർ\n\nഗുരു\n\nശ്രീ മഹർഷി ഒരു ഗുരു ആവശ്യമാണ് എന്ന് പറഞ്ഞു. അദ്ദേഹം ഗുരു പുറംഭാഗത്ത് ഉണ്ടാകേണ്ടതില്ല എന്നും പറഞ്ഞു, അദ്ദേഹത്തിന്റെ കേസിൽ പോലെ. മരണാനന്തരത്തിൽ അദ്ദേഹം പറഞ്ഞു, അവൻ വിടുന്നില്ല, കാരണം അവൻ ശരീരത്തോടൊപ്പമല്ല; അതായത്, അദ്ദേഹം ഇപ്പോഴും സാന്നിധ്യത്തിലാണ്. \n\nസത്യമാണ്, ആരും നമ്മെ മോചിതരാക്കാൻ കഴിയില്ല. വഴി കാണിക്കാം, നിർദ്ദേശങ്ങൾ നൽകാം. നമ്മുടെ ശക്തമായ ആഗ്രഹവും ലക്ഷ്യത്തിലേക്കുള്ള സമ്പൂർണ്ണ സമർപ്പണവും ഏറ്റവും പ്രധാനപ്പെട്ട ഘടകമാണ്. ഈ ഒരു കാര്യത്തിൽ - സത്യത്തെ തിരിച്ചറിഞ്ഞാൽ - സത്യവും, ശാരീരിക ഗുരുവും (ആവശ്യമെങ്കിൽ) എല്ലാം സ്വാഭാവികമായി നമ്മെ ആകർഷിക്കും. നമ്മൾ തയ്യാറായപ്പോൾ ഗുരു നമ്മെ കാണും. നമ്മൾ നമ്മെ തയ്യാറാക്കുന്നതിൽ ശ്രദ്ധിക്കേണ്ടതാണ്, ശേഷമുള്ളത് സ്വാഭാവികമാണ്. മഹർഷിയുടെ ജീവിച്ചിരിക്കുന്ന സാന്നിധ്യത്തിൽ വിശ്വാസമുള്ളവർക്കു ഈ കാര്യത്തിൽ സംശയങ്ങളില്ല.'
    ),
    Article(
        heading: 'ഞാൻ ആരാണ് - മഹർഷി രാമണന്റെ ഏക പുസ്തകം',
        body: 'ഓം നമോ ഭഗവതേ ശ്രീ രാമനായ\\n\\nഞാൻ ആരാണ്?\\n\\n(ഞാൻ ആര?)\\n\\nഎല്ലാ ജീവികളുടെയും ആഗ്രഹം എപ്പോഴും സന്തോഷത്തിലായിരിക്കുകയാണ്, ദു:ഖം ഇല്ലാതെ, എല്ലാവരുടെയും ആത്മനിഷ്ഠയ്ക്കുള്ള ഉന്നതമായ സ്നേഹം കാണപ്പെടുന്നു, സന്തോഷം മാത്രമാണ് സ്നേഹത്തിന്റെ കാരണം. അതിനാൽ, ആ സന്തോഷം നേടാൻ, അത് വ്യക്തിയുടെ സ്വഭാവമാണ്, ദീപ സ്വപ്നത്തിന്റെ അവസ്ഥയിൽ അനുഭവപ്പെടുന്നു, അവിടെ മനസ്സില്ല. അതിനാൽ, വ്യക്തിയെ അറിയേണ്ടതാണ്. അതിന്, അറിവിന്റെ പാത, "ഞാൻ ആര?" എന്ന രൂപത്തിൽ ഉള്ള അന്വേഷണമാണ് പ്രധാന മാർഗം.\\n\\n1. ഞാൻ ആര?\\n\\nഏഴു ധാതുക്കളാൽ രൂപപ്പെട്ട ഭൗതിക ശരീരം ഞാൻ അല്ല; അഞ്ചു ബോധനേന്ദ്രിയങ്ങൾ, അഥവാ കേൾവിയുടെ, സ്പർശത്തിന്റെ, കാഴ്ചയുടെ, രുചിയുടെ, മണത്തിന്റെ, അവയുടെ അനുബന്ധവസ്തുക്കളെ ഗ്രഹിക്കുന്നവ, അഥവാ. ശബ്ദം, സ്പർശം, നിറം, രുചി, ഗന്ധം, ഞാൻ അല്ല; അഞ്ചു ബോധനാത്മക ഇന്ദ്രിയങ്ങൾ, അതായത് വാക്കിന്റെ, ചലനത്തിന്റെ, പിടിക്കുന്നതിന്റെയും, പുറവിടുന്നതിന്റെയും, പ്രജനനത്തിന്റെയും പ്രവർത്തനങ്ങൾ സംസാരിക്കുക, ചലിക്കുക, പിടിക്കുക, പുറവിടുക, ആസ്വദിക്കുക എന്നിവ, ഞാൻ അല്ല; അഞ്ചു പ്രാണവായുകൾ, പ്രാണം മുതലായവ, ശ്വാസം എടുക്കൽ, തുടങ്ങിയവയുടെ അഞ്ചു പ്രവർത്തനങ്ങൾ നിർവഹിക്കുന്ന, ഞാൻ അല്ല; ചിന്തിക്കുന്ന മനസും, ഞാൻ അല്ല; വസ്തുക്കളുടെ ശേഷിപ്പായ മുദ്രകളാൽ മാത്രം സമ്പന്നമായ അവബോധവും, അവയിൽ വസ്തുക്കളും പ്രവർത്തനങ്ങളും ഇല്ലാത്തതും, ഞാൻ അല്ല. \n\n2. ഞാൻ ഇതിൽ ഒന്നുമല്ലെങ്കിൽ, ഞാൻ ആരാണ്?\n\nമുകളിൽ പറഞ്ഞവയെ \'ഇല്ല\' എന്ന് നിഷേധിച്ച ശേഷം, മാത്രം ശേഷിക്കുന്ന അവബോധം - അത് ഞാൻ ആണ്. അവബോധത്തിന്റെ സ്വഭാവം എന്താണ്?\\n\\nഅവബോധത്തിന്റെ സ്വഭാവം അസ്തിത്വ-ബോധം-ആനന്ദം ആണ്.\\n\\n4. ആത്മാവിന്റെ അനുഭവം എപ്പോൾ ലഭിക്കും?\\n\\nഎന്ത് കാണപ്പെടുന്നുവെന്നത് നീക്കം ചെയ്താൽ, കാണുന്ന ആത്മാവിന്റെ അനുഭവം ലഭിക്കും.\\n\\n5. ലോകം ഉണ്ടാകുമ്പോൾ (യാഥാർത്ഥ്യമായി എടുത്താൽ) ആത്മാവിന്റെ അനുഭവം ഉണ്ടാകില്ലേ?\\n\\nഉണ്ടാകില്ല.\\n\\n6. എന്തുകൊണ്ട്?\\n\\nകാണുന്നവനും കാണപ്പെടുന്നവനും നൂലും പാമ്പും പോലെയാണ്. ഭ്രാന്തമായ പാമ്പിന്റെ തെറ്റായ അറിവ് ഇല്ലാതാകാതെ, അടിസ്ഥാനമായ നൂലിന്റെ അറിവ് ഉണ്ടാകില്ല; അതുപോലെ, ലോകം യാഥാർത്ഥ്യമാണെന്ന വിശ്വാസം നീക്കം ചെയ്യാതെ, അടിസ്ഥാനമായ ആത്മാവിന്റെ അനുഭവം ലഭിക്കില്ല. ലോകം, കാണപ്പെടുന്ന വസ്തുവായ, എപ്പോൾ നീക്കം ചെയ്യും?\\n\\nഎല്ലാ അറിവുകളും എല്ലാ പ്രവർത്തനങ്ങളും ഉണ്ടാക്കുന്ന കാരണം ആയ മനസ്സ് ശാന്തമായപ്പോൾ, ലോകം അപ്രത്യക്ഷമാകും.\\n\\n8. മനസ്സിന്റെ സ്വഭാവം എന്താണ്?\\n\\n‘മനസ്സ്’ എന്ന് വിളിക്കുന്നതു ആത്മയിൽ നിക്ഷിപ്തമായ ഒരു അത്ഭുതശക്തിയാണ്. ഇത് എല്ലാ ചിന്തകൾക്കും ഉദയം നൽകുന്നു.\\n\\nചിന്തകളെ ഒഴികെ, മനസ്സെന്നുവേണ്ടിയുള്ള ഒരു വസ്തുവില്ല. അതിനാൽ, ചിന്തയാണ് മനസ്സിന്റെ സ്വഭാവം. ചിന്തകളെ ഒഴികെ, ലോകം എന്ന പേരിൽ ഒരു സ്വതന്ത്ര സത്തയില്ല. ആഴത്തിലുള്ള ഉറക്കത്തിൽ ചിന്തകളില്ല, ലോകമില്ല. ഉണർവിലും സ്വപ്നത്തിലുമുള്ള അവസ്ഥകളിൽ, ചിന്തകളും ലോകവും ഉണ്ട്. പുഴു തന്റെ തൂവലിന്റെ തന്തു പുറത്തുവിടുകയും വീണ്ടും അതിനെ തന്റെ ഉള്ളിലേക്ക് തിരിച്ചു കൊണ്ടുപോകുകയും ചെയ്യുന്ന വിധത്തിൽ, മനസ്സ് അതിന്റെ ഉള്ളിൽ നിന്നു ലോകത്തെ പുറത്തു പ്രക്ഷിപ്തമാക്കുകയും, വീണ്ടും അതിനെ അതിന്റെ ഉള്ളിലേക്ക് പുനഃസംയോജിപ്പിക്കുകയും ചെയ്യുന്നു. മനസ്സ് ആത്മാവിൽ നിന്നു പുറത്തു വന്നാൽ, ലോകം പ്രത്യക്ഷപ്പെടുന്നു. അതിനാൽ, ലോകം പ്രത്യക്ഷപ്പെടുമ്പോൾ (യാഥാർത്ഥ്യമായതായി) ആത്മാവ് പ്രത്യക്ഷപ്പെടുന്നില്ല; ആത്മാവ് പ്രത്യക്ഷപ്പെടുമ്പോൾ (പ്രകാശം പകരുമ്പോൾ) ലോകം പ്രത്യക്ഷപ്പെടുന്നില്ല. ഒരാൾ മനസ്സിന്റെ സ്വഭാവത്തെ സ്ഥിരമായി അന്വേഷിക്കുമ്പോൾ, മനസ്സ് അവസാനിക്കും, ആത്മാവ് (ശേഷിപ്പായി) ബാക്കി ഉണ്ടാകും. ആത്മാവിനെ സൂചിപ്പിക്കുന്നത് ആത്‌മയാണ്. മനസ്സ് എല്ലായ്പ്പോഴും ഏതെങ്കിലും ഭൗതികത്വത്തിൽ ആശ്രയിച്ചിരിക്കുന്നു; അത് ഒറ്റയ്ക്ക് നിലനിൽക്കാൻ കഴിയുന്നില്ല. മനസ്സിനെ സൂചിപ്പിക്കുന്നത് സൂക്ഷ്മശരീരം അല്ലെങ്കിൽ ആത്മാവ് (ജിവ) എന്നാണ്. മനസ്സിന്റെ സ്വഭാവം മനസ്സിലാക്കാനുള്ള അന്വേഷണത്തിന്റെ പാത എന്താണ്?\\n\\nഈ ശരീരത്തിൽ \'ഞാൻ\' എന്ന രൂപത്തിൽ ഉയരുന്നത് മനസ്സാണ്. \'ഞാൻ\' എന്ന ചിന്ത ശരീരത്തിൽ എവിടെ ആദ്യം ഉയരുന്നു എന്ന് അന്വേഷിച്ചാൽ, അത് ഹൃദയത്തിൽ ഉയരുന്നുവെന്ന് കണ്ടെത്തും. അതാണ് മനസ്സിന്റെ ഉദ്ഭവസ്ഥലം. ഒരാൾ സ്ഥിരമായി \'ഞാൻ\' \'ഞാൻ\' എന്ന് ചിന്തിച്ചാലും, അവൻ ആ സ്ഥലത്തേക്ക് നയിക്കപ്പെടും. മനസ്സിൽ ഉയരുന്ന എല്ലാ ചിന്തകളിൽ, \'ഞാൻ\' എന്ന ചിന്തയാണ് ആദ്യം. ഇതിന്റെ ഉയർച്ചയ്ക്ക് ശേഷം മാത്രമേ മറ്റ് ചിന്തകൾ ഉയരുകയുള്ളൂ. ആദ്യ വ്യക്തിപ്രണാമത്തിന്റെ പ്രത്യക്ഷതയ്ക്ക് ശേഷം മാത്രമേ രണ്ടാം, മൂന്നാം വ്യക്തിപ്രണാമങ്ങൾ പ്രത്യക്ഷപ്പെടുകയുള്ളൂ; ആദ്യ വ്യക്തിപ്രണാമം ഇല്ലാതെ രണ്ടാം, മൂന്നാം ഉണ്ടാകില്ല.\\n\\n10. മനസ്സ് എങ്ങനെ ശാന്തമാകും?\\n\\n\'ഞാൻ ആരാണ്?\' എന്ന അന്വേഷണത്തിലൂടെ. \'ഞാൻ ആരാണ്?\' എന്ന ചിന്ത എല്ലാ മറ്റ് ചിന്തകളെയും നശിപ്പിക്കും, കൂടാതെ തീയിൽ കത്തുന്ന കുഴലുകൾ stir ചെയ്യാൻ ഉപയോഗിക്കുന്ന കെട്ടുപോലെ, അത് തന്നെ അവസാനം നശിക്കും. അപ്പോൾ, ആത്മസാക്ഷാത്കാരം ഉണ്ടാകും.\n\n11. \'ഞാൻ ആരാണ്?\' എന്ന ചിന്തയെ സ്ഥിരമായി പിടിച്ചിരിക്കാൻ എന്താണ് മാർഗം?\n\nമറ്റു ചിന്തകൾ ഉയർന്നാൽ, അവയെ പിന്തുടരേണ്ടതില്ല, മറിച്ച് ചോദിക്കണം: \'അവ എവിടെ നിന്നാണ് ഉയർന്നത്?\' എത്ര ചിന്തകൾ ഉയർന്നാലും അതിന് എന്തെങ്കിലും പ്രാധാന്യമില്ല. ഓരോ ചിന്തയും ഉയർന്നപ്പോൾ, ഒരു ശ്രദ്ധയോടെ ചോദിക്കണം, "ഈ ചിന്ത ആരുടെ?" ഉത്തരം "എന്റെ" എന്നാകും. അതിനുശേഷം "ഞാൻ ആരാണ്?" എന്ന ചോദ്യം ചോദിച്ചാൽ, മനസ്സ് അതിന്റെ ഉറവിടത്തിലേക്ക് മടങ്ങും; ഉയർന്ന ചിന്ത ശാന്തമാകും. ഈ രീതിയിൽ ആവർത്തിച്ച പരിശീലനത്തോടെ, മനസ്സ് അതിന്റെ ഉറവിടത്തിൽ നിൽക്കാനുള്ള കഴിവ് വികസിപ്പിക്കും. മനസ്സിന്റെ സൂക്ഷ്മത ബുദ്ധിയും ഇന്ദ്രിയങ്ങളിലൂടെ പുറത്തേക്ക് പോകുമ്പോൾ, ഭൗതികമായ നാമങ്ങളും രൂപങ്ങളും പ്രത്യക്ഷപ്പെടുന്നു; അത് ഹൃദയത്തിൽ നിൽക്കുമ്പോൾ, നാമങ്ങളും രൂപങ്ങളും അപ്രത്യക്ഷമാകുന്നു. മനസ്സിനെ പുറത്തേക്ക് പോകാൻ അനുവദിക്കാതെ, ഹൃദയത്തിൽ നിലനിർത്തുന്നത് “ആന്തരികത” (antarmukha) എന്ന് വിളിക്കുന്നു. ഹൃദയത്തിൽ നിന്ന് മനസ്സിനെ പുറത്തേക്ക് പോകാൻ അനുവദിക്കുന്നത് “ബാഹ്യീകരണം” (bahir-mukha) എന്നറിയപ്പെടുന്നു. അതിനാൽ, മനസ്സ് ഹൃദയത്തിൽ നിൽക്കുമ്പോൾ, എല്ലാ ചിന്തകളുടെ ഉറവിടമായ ‘ഞാൻ’ ഇല്ലാതാകും, എല്ലായ്പ്പോഴും ഉണ്ട് എന്ന ആത്മാവ് പ്രകാശിക്കും. ഒരാൾ ചെയ്യുന്നതെല്ലാം, ‘ഞാൻ’ എന്ന അഹങ്കാരമില്ലാതെ ചെയ്യണം. അങ്ങനെ പ്രവർത്തിച്ചാൽ, എല്ലാം ശിവന്റെ (ദൈവത്തിന്റെ) സ്വഭാവത്തിൽ പ്രത്യക്ഷപ്പെടും.\n\n12. മനസ്സിനെ ശാന്തമാക്കാൻ മറ്റൊരു മാർഗമില്ലേ?\n\nഅന്വേഷണത്തെ ഒഴികെ, യോജ്യമായ മാർഗങ്ങൾ ഇല്ല. മറ്റു മാർഗ്ഗങ്ങളിലൂടെ മനസ്സിനെ നിയന്ത്രിക്കാൻ ശ്രമിക്കുമ്പോൾ, മനസ്സിനെ നിയന്ത്രിതമായതായി തോന്നിച്ചേക്കാം, എന്നാൽ അത് വീണ്ടും പുറത്ത് പോകും. ശ്വാസത്തെ നിയന്ത്രിച്ചാൽ, മനസ്സ് ശാന്തമാകും; പക്ഷേ, ശ്വാസം നിയന്ത്രിതമായിരിക്കുമ്പോൾ മാത്രമേ അത് ശാന്തമാകൂ, ശ്വാസം വീണ്ടും സ്വാഭാവികമായി നടക്കുമ്പോൾ മനസ്സ് വീണ്ടും ചലിക്കാനും ശേഷിക്കുന്ന സ്വാധീനങ്ങളാൽ ആകർഷിക്കപ്പെടാനും തുടങ്ങും. മനസ്സും ശ്വാസവും ഒരേ ഉറവിടത്തിൽ നിന്നാണ്. ചിന്ത, വാസ്തവത്തിൽ, മനസ്സിന്റെ സ്വഭാവമാണ്. "ഞാൻ" എന്ന ചിന്തയാണ് മനസ്സിന്റെ ആദ്യ ചിന്ത; അതാണ് എഗോത്വം. എഗോത്വം ഉദ്ഭവിക്കുന്നതിൽ നിന്നാണ് ശ്വാസവും ഉദ്ഭവിക്കുന്നത്. അതിനാൽ, മനസ്സ് ശാന്തമാകുമ്പോൾ, ശ്വാസം നിയന്ത്രിതമാകുന്നു, ശ്വാസം നിയന്ത്രിതമാകുമ്പോൾ മനസ്സ് ശാന്തമാകുന്നു. എന്നാൽ ആഴത്തിലുള്ള ഉറക്കത്തിൽ, മനസ്സ് ശാന്തമാകുമ്പോഴും, ശ്വാസം നിർത്തുന്നില്ല. ഇത് ദൈവത്തിന്റെ ഇച്ഛയാൽ ആണ്, ശരീരം സംരക്ഷിക്കപ്പെടുകയും മറ്റുള്ളവർ അത് മരിച്ചെന്ന് കരുതുന്നില്ലാത്തതിനും. ഉണർവിന്റെ അവസ്ഥയിൽയും സമാധിയിൽ, മനസ്സ് ശാന്തമാകുമ്പോൾ ശ്വാസം നിയന്ത്രിക്കപ്പെടുന്നു. \n\nശ്വാസം മനസ്സിന്റെ ഭൗതിക രൂപമാണ്. മരണം വരെയുള്ള കാലയളവിൽ, മനസ്സ് ശരീരത്തിൽ ശ്വാസത്തെ സൂക്ഷിക്കുന്നു; ശരീരം മരിച്ചപ്പോൾ മനസ്സ് ശ്വാസത്തെ കൂടെ കൊണ്ടുപോകുന്നു. അതിനാൽ, ശ്വാസ നിയന്ത്രണത്തിന്റെ അഭ്യാസം മനസ്സിനെ ശാന്തമാക്കുന്നതിനുള്ള ഒരു സഹായമാണ് (മനോനിഗ്രഹ); ഇത് മനസ്സിനെ നശിപ്പിക്കുകയല്ല (മനോനാശ). ശ്വാസ നിയന്ത്രണത്തിന്റെ അഭ്യാസം, ദൈവത്തിന്റെ രൂപങ്ങളിൽ ധ്യാനം, മന്ത്രങ്ങളുടെ ആവർത്തനം, ഭക്ഷണത്തിൽ നിയന്ത്രണം എന്നിവ മനസ്സിനെ ശാന്തമാക്കുന്നതിനുള്ള സഹായങ്ങളാണ്. ദൈവത്തിന്റെ രൂപങ്ങളിൽ ധ്യാനം ചെയ്ത്, മന്ത്രങ്ങളുടെ ആവർത്തനത്തിലൂടെ, മനസ്സ് ഏകദൃഷ്ടിയാകുന്നു. മനസ്സ് എപ്പോഴും ഭ്രമണത്തിലായിരിക്കും. ഒരു ആനയ്ക്ക് തൻ്റെ കൊമ്പിൽ പിടിക്കാൻ ഒരു ശൃംഖല നൽകുമ്പോൾ, ആ ആന ആ ശൃംഖല പിടിച്ചുകൊണ്ടു മാത്രമേ മുന്നോട്ടു പോവുകയുള്ളൂ, മറ്റൊന്നും അല്ല; അതുപോലെ, മനസ്സ് ഒരു നാമം അല്ലെങ്കിൽ രൂപത്തിൽ ഏർപ്പെടുമ്പോൾ, അത് ആ ഏകമായത് മാത്രം പിടിക്കും. മനസ്സ് അനേകം ചിന്തകളുടെ രൂപത്തിൽ വ്യാപിക്കുമ്പോൾ, ഓരോ ചിന്തയും ദുർബലമാകുന്നു; എന്നാൽ ചിന്തകൾ പരിഹരിക്കപ്പെടുമ്പോൾ, മനസ്സ് ഏകദൃഷ്ടിയാകുകയും ശക്തമായിത്തീരുകയും ചെയ്യുന്നു; അത്തരം ഒരു മനസ്സിന് ആത്മാവിനുള്ള അന്വേഷണവും എളുപ്പമാകും. നിയന്ത്രണങ്ങളിലെല്ലാം, സാത്ത്വികമായ ഭക്ഷണം മിതമായ അളവിൽ സ്വീകരിക്കുന്നതുമായി ബന്ധപ്പെട്ട നിയമം ഏറ്റവും നല്ലതാണ്; ഈ നിയമം പാലിച്ചാൽ, മനസ്സിന്റെ സാത്ത്വിക ഗുണം വർദ്ധിക്കും, അത് ആത്മാവിനുള്ള അന്വേഷണത്തിന് സഹായകമായിരിക്കും. 13. വസ്തുക്കളുടെ ശേഷിച്ച പ്രതിബിംബങ്ങൾ സമുദ്രത്തിന്റെ തരംഗങ്ങൾ പോലെ തിരിയുന്നതായി കാണപ്പെടുന്നു. അവയെല്ലാം എപ്പോൾ നശിക്കും? ആത്മാവിൽ ധ്യാനം ഉയർന്നുപോകുമ്പോൾ, ആ ചിന്തകൾ നശിക്കും. 14. ആരംഭമില്ലാത്ത കാലം മുതൽ വരുന്ന വസ്തുക്കളുടെ ശേഷിച്ച പ്രതിബിംബങ്ങൾ പരിഹരിക്കാവുന്നതാണോ, ഒരാൾ ശുദ്ധമായ ആത്മാവായി നിലനിൽക്കാൻ കഴിയുമോ? "സാധ്യമാണോ, അല്ലയോ?" എന്ന സംശയത്തിന് കീഴടങ്ങാതെ, ഒരാൾ ആത്മാവിൽ ധ്യാനം തുടരണം. ഒരാൾ വലിയ പാപി ആയാലും, "ഓ! ഞാൻ ഒരു പാപി, എങ്ങനെ രക്ഷപ്പെടാം?" എന്ന ആശങ്കയിൽ പെടരുത്; "ഞാൻ ഒരു പാപി" എന്ന ചിന്തയെ പൂർണ്ണമായും ഉപേക്ഷിച്ച്, ആത്മാവിൽ ധ്യാനത്തിൽ ശ്രദ്ധ കേന്ദ്രീകരിക്കണം; അപ്പോൾ, ഒരാൾ തീർച്ചയായും വിജയിക്കും. രണ്ടു മനസ്സുകൾ ഇല്ല - ഒരു നല്ലത്, മറ്റൊരു ദുഷ്ടം; മനസ്സ് ഒറ്റതാണ്. ഇത് രണ്ട് തരത്തിലുള്ള ശേഷി പ്രഭാവങ്ങൾ ആണ് - ശുഭവും അശുഭവും. മനസ്സ് ശുഭ പ്രഭാവങ്ങളുടെ സ്വാധീനത്തിൽ ആയിരിക്കുമ്പോൾ അത് നല്ലതെന്ന് വിളിക്കപ്പെടുന്നു; അശുഭ പ്രഭാവങ്ങളുടെ സ്വാധീനത്തിൽ ആയിരിക്കുമ്പോൾ അത് ദുഷ്ടമായി കണക്കാക്കപ്പെടുന്നു. മനസ്സിനെ ലോകീയ വസ്തുക്കളിലേക്കും മറ്റുള്ളവരുടെ കാര്യങ്ങളിലേക്കും ആകർഷിക്കാനായി വിട്ടുകൂടാൻ അനുവദിക്കരുത്. മറ്റുള്ളവർ എത്ര മോശമായാലും, അവരോടു hatred തോന്നിക്കരുത്. ആഗ്രഹവും hatredയും ഒഴിവാക്കണം. മറ്റുള്ളവരെ നൽകുന്ന എല്ലാം, ഒരാളുടെ തന്നെ നൽകുകയാണ്. ഈ സത്യം മനസ്സിലായാൽ, ആരും മറ്റുള്ളവരെ നൽകാൻ തയ്യാറാവില്ലേ? ഒരാളുടെ ആത്മാവ് ഉണർന്നാൽ എല്ലാം ഉണരുന്നു; ഒരാളുടെ ആത്മാവ് നിശ്ചലമായാൽ എല്ലാം നിശ്ചലമാകുന്നു. നമ്രതയോടെ പെരുമാറുന്നത്ര, അത്രയും നല്ലതുണ്ടാകും. മനസ്സിനെ ശാന്തമാക്കുമ്പോൾ, ആരും എവിടെയായാലും ജീവിക്കാം. 15. അന്വേഷണം എത്രകാലം നടത്തണം?\\n\\nമനസ്സിൽ വസ്തുക്കളുടെ അടയാളങ്ങൾ ഉണ്ടാകുന്നത്ര, “ഞാൻ ആരാണ്?” എന്ന ചോദ്യം ആവശ്യമാണ്. ചിന്തകൾ ഉയർന്നാൽ, അവയുടെ ഉത്ഭവസ്ഥലത്തേയ്ക്ക് തന്നെ, അന്വേഷണത്തിലൂടെ അവ നശിപ്പിക്കണം. ആത്മാവിനെ കൈവശമാക്കുന്നതുവരെ, നിരന്തരമായി ആത്മാവിനെ ധ്യാനിക്കുന്നത് മാത്രം മതിയാകും. കോട്ടയിൽ ഉള്ള ശത്രുക്കൾ ഉണ്ടാകുമ്പോൾ, അവർ പുറത്തേക്ക് വരുന്നതു തുടരും; അവർ പുറത്തു വന്നപ്പോൾ നശിപ്പിക്കപ്പെടുകയാണെങ്കിൽ, കോട്ട നമ്മുടെ കൈയിൽ വീഴും.\\n\\n16. ആത്മാവിന്റെ സ്വഭാവം എന്താണ്?\\n\\nസത്യത്തിൽ ഉള്ളത് മാത്രം ആത്മാവാണ്. ലോകം, വ്യക്തി ആത്മാവ്, ദൈവം എന്നിവ അതിൽ പ്രത്യക്ഷമാകുന്നു. മുത്തിന്റെ വെള്ളിയിൽ വെള്ളി പോലെ, ഈ മൂന്നു ഒരേസമയം പ്രത്യക്ഷപ്പെടുകയും ഒരേസമയം അപ്രത്യക്ഷമാകുകയും ചെയ്യുന്നു. "ഞാൻ" എന്ന ചിന്ത ഇല്ലാത്തതാണ് ആത്മാവ്. അതിനെ "ശാന്തി" എന്ന് വിളിക്കുന്നു. ആത്മാവാണ് ലോകം; ആത്മാവാണ് "ഞാൻ"; ആത്മാവാണ് ദൈവം; എല്ലാം ശിവമാണ്, ആത്മാവ്. 17. എല്ലാം ദൈവത്തിന്റെ പ്രവർത്തിയല്ലേ?\n\nആഗ്രഹം, തീരുമാനമോ, പരിശ്രമമോ ഇല്ലാതെ, സൂര്യൻ ഉദിക്കുന്നു; അതിന്റെ സാന്നിധ്യത്തിൽ, സൂര്യരത്നം തീ പകരുന്നു, കമല പൂക്കുന്നു, വെള്ളം വाष്പീകരിക്കുന്നു; ആളുകൾ അവരുടെ വിവിധ പ്രവർത്തനങ്ങൾ നടത്തുകയും പിന്നീട് വിശ്രമിക്കുകയും ചെയ്യുന്നു. മാഗ്നറ്റിന്റെ സാന്നിധ്യത്തിൽ നൂലിക നീങ്ങുന്നതുപോലെ, മൂന്ന് (കോസ്മിക്) പ്രവർത്തനങ്ങൾ അല്ലെങ്കിൽ അഞ്ചു ദിവ്യ പ്രവർത്തനങ്ങൾ നിയന്ത്രിക്കുന്ന ആത്മാക്കൾ അവരുടെ കര്‍മങ്ങൾ അനുസരിച്ച് പ്രവർത്തിക്കുകയും പിന്നീട് വിശ്രമിക്കുകയും ചെയ്യുന്നത്, ദൈവത്തിന്റെ സാന്നിധ്യത്തിന്റെ ശക്തിയാൽ മാത്രമാണ്. ദൈവത്തിന് യാതൊരു തീരുമാനവും ഇല്ല; അവനോട് യാതൊരു കര്‍മവും ബന്ധപ്പെടുന്നില്ല. ഇത് ഭൂതിക പ്രവർത്തനങ്ങൾ സൂര്യനെ ബാധിക്കാത്തതുപോലെയാണ്, അല്ലെങ്കിൽ മറ്റ് നാലു മൂലകങ്ങളുടെ ഗുണങ്ങളും ദോഷങ്ങളും സമസ്തമായ ആകാശത്തെ ബാധിക്കാത്തതുപോലെയാണ്.\n\n18. ഭക്തന്മാരിൽ, ഏറ്റവും മഹാനവൻ ആരാണ്?\n\nദൈവമായ ആത്മാവിലേക്ക് തന്റെ ആത്മാവിനെ സമർപ്പിക്കുന്നവൻ ഏറ്റവും ഉത്തമമായ ഭക്തനാണ്. ദൈവത്തിൽ ആത്മാവിനെ സമർപ്പിക്കുന്നത്, ആത്മാവിന്റെ ചിന്തകൾ ഉയരാൻ ഇടവരുത്താതെ, സ്ഥിരമായി ആത്മാവിൽ തുടരുന്നതാണ്. ദൈവത്തിന് ഏത് ഭാരം എറിയുകയാണെങ്കിൽ, അവൻ അവയെ സഹിക്കുകയാണ്. ദൈവത്തിന്റെ പരമ ശക്തി എല്ലാ കാര്യങ്ങളും ചലിപ്പിക്കുന്നതിനാൽ, അതിന് കീഴടങ്ങാതെ നാം എന്ത് ചെയ്യണം, എങ്ങനെ ചെയ്യണം, എന്ത് ചെയ്യരുത്, എങ്ങനെ ചെയ്യരുത് എന്നതിൽ നിരന്തരം ആശങ്കപ്പെടേണ്ടതെന്താണ്? ട്രെയിൻ എല്ലാ ഭാരം വഹിക്കുന്നുവെന്ന് നാം അറിയുന്നു, അതിൽ കയറുന്നതിന് ശേഷം, നമ്മുടെ ചെറിയ ബാഗുകൾ തലയിൽ വഹിച്ച് അസൗകര്യപ്പെടേണ്ടതെന്താണ്? അതിനെ ട്രെയിനിൽ വെച്ച് സമാധാനമായി ഇരിക്കേണ്ടതല്ലേ?\n\n19. അസംഗത്വം എന്താണ്?\n\nചിന്തകൾ ഉയർന്നപ്പോൾ, അവയുടെ ഉൽപത്തി സ്ഥലത്തുതന്നെ അവയെ മുഴുവൻ നശിപ്പിക്കുക എന്നത് അസംഗത്വമാണ്. മുത്തു പിടിക്കാൻ പാറ ഒരു കെട്ടിയിട്ടു കടലിന്റെ താഴ്ചയിൽ മുങ്ങുന്ന മുത്തുപിടുത്തക്കാരൻ പോലെ, ഓരോരുത്തരും അസംഗത്വത്തോടെ, സ്വയം ആഴത്തിൽ മുങ്ങി ആത്മ-മുത്തു നേടണം. ദൈവവും ഗുരുവും ഒരു ആത്മാവിനെ മോചിപ്പിക്കാൻ സാധിക്കുകയല്ലേ? ദൈവവും ഗുരുവും മോചനം കാണിക്കുന്ന വഴിയാകും മാത്രം; അവർ സ്വയം ആത്മാവിനെ മോചനത്തിന്റെ അവസ്ഥയിലേക്ക് കൊണ്ടുപോകുകയില്ല. സത്യത്തിൽ, ദൈവവും ഗുരുവും വ്യത്യസ്തമല്ല. കടുവയുടെ വായിൽ വീഴുന്ന ശിക്ഷിതന്റെ escape ഇല്ലാത്തതുപോലെ, ഗുരുവിന്റെ കരുണയുള്ള കാഴ്ചയിൽ വന്നവരെ ഗുരു രക്ഷിക്കും, അവർ നഷ്ടപ്പെടുകയില്ല; എങ്കിലും, ഓരോരുത്തരും ദൈവം അല്ലെങ്കിൽ ഗുരു കാണിച്ച വഴിയെ പിന്തുടർന്ന് മോചനം നേടേണ്ടതാണ്. ഒരാൾ തന്റെ അറിവിന്റെ കണ്ണിലൂടെ മാത്രമേ സ്വയം അറിയാൻ കഴിയൂ, മറ്റൊരാളുടെ കണ്ണിലൂടെ അല്ല. രാമനാണ് എന്ന് അറിയാൻ ഒരു കട്ടിലിന്റെ സഹായം ആവശ്യമുണ്ടോ? മുക്തി ആഗ്രഹിക്കുന്നവനു തത്ത്വങ്ങളുടെ സ്വഭാവം അന്വേഷിക്കുന്നത് അനിവാര്യമാണോ? \n\nകഴിവില്ലാത്തവൻ കച്ചവടം തള്ളാൻ ആഗ്രഹിക്കുന്നുവെങ്കിൽ, അതിനെ വിശകലനം ചെയ്യേണ്ടതില്ല; അതുപോലെ തന്നെ, ആത്മാവിനെ അറിയാൻ ആഗ്രഹിക്കുന്നവനു തത്ത്വങ്ങളുടെ എണ്ണം എണ്ണേണ്ടതോ അവയുടെ പ്രത്യേകതകളെ അന്വേഷിക്കേണ്ടതോ ഇല്ല; അവൻ ചെയ്യേണ്ടത്, ആത്മാവിനെ മറയ്ക്കുന്ന തത്ത്വങ്ങളെ മുഴുവനും നിരസിക്കുകയാണ്. ലോകം ഒരു സ്വപ്നം പോലെ കണക്കാക്കപ്പെടണം.\n\n22. ഉണർവും സ്വപ്നവും തമ്മിൽ വ്യത്യാസമില്ലേ?\n\nഉണർവ് നീണ്ടതും സ്വപ്നം ചെറുതും; ഇതിന് പുറമേ വ്യത്യാസമില്ല. ഉണർവിൽ സംഭവിക്കുന്നവകൾ ഉണർന്നിരിക്കുന്നപ്പോൾ യാഥാർത്ഥ്യമെന്നു തോന്നുന്നു; സ്വപ്നത്തിൽ ഉണ്ടായവയും സ്വപ്നം കാണുമ്പോൾ യാഥാർത്ഥ്യമെന്നു തോന്നുന്നു. സ്വപ്നത്തിൽ മനസ്സ് മറ്റൊരു ശരീരം സ്വീകരിക്കുന്നു. ഉണർവിലും സ്വപ്നത്തിലും ചിന്തകൾ, പേരുകൾ, രൂപങ്ങൾ ഒരേസമയം ഉണ്ടാവുന്നു. മുക്തിയിലേക്കുള്ള ആഗ്രഹം ഉള്ളവർക്കു പുസ്തകങ്ങൾ വായിക്കുന്നത് എത്രത്തോളം പ്രയോജനകരമാണ്? \\n\\nമുക്തി നേടാൻ മനസ്സിനെ ശാന്തമാക്കണം എന്നതാണ് എല്ലാ ഗ്രന്ഥങ്ങളും പറയുന്നത്; അതിനാൽ അവരുടെ അന്തിമ ഉപദേഷ്ടാവ് മനസ്സിനെ ശാന്തമാക്കേണ്ടതാണെന്ന് തന്നെയാണ്; ഇത് മനസ്സിലായാൽ, അനന്തമായ വായനയുടെ ആവശ്യമില്ല. മനസ്സിനെ ശാന്തമാക്കാൻ, വ്യക്തിയുടെ ആത്മാവ് എന്താണെന്ന് സ്വയം അന്വേഷിക്കേണ്ടതാണ്; ഈ അന്വേഷണം പുസ്തകങ്ങളിൽ എങ്ങനെ നടത്താം? വ്യക്തി തന്റെ ആത്മാവിനെ തന്റെ ജ്ഞാനദൃഷ്ടിയാൽ അറിയണം. ആത്മാവ് അഞ്ചു കവചങ്ങളിൽ ഉള്ളതാണ്; എന്നാൽ പുസ്തകങ്ങൾ അവയുടെ പുറത്താണ്. ആത്മാവിനെ അഞ്ചു കവചങ്ങൾ ഉപേക്ഷിച്ച് അന്വേഷിക്കേണ്ടതുകൊണ്ടു, പുസ്തകങ്ങളിൽ അതിനെ അന്വേഷിക്കുന്നത് വ്യർത്ഥമാണ്. ഒരിക്കൽ, ഒരാൾ പഠിച്ചിട്ടുള്ള എല്ലാ കാര്യങ്ങളും മറക്കേണ്ട സമയം വരും. സന്തോഷം എന്താണ്?\\n\\nസന്തോഷം ആത്മാവിന്റെ സ്വഭാവമാണ്; സന്തോഷവും ആത്മാവും വ്യത്യസ്തമല്ല. ലോകത്തിലെ ഏതെങ്കിലും വസ്തുവിൽ സന്തോഷം ഇല്ല. നാം അറിവിന്റെ അഭാവത്തിൽ വസ്തുക്കളിൽ നിന്നാണ് സന്തോഷം ലഭിക്കുന്നുവെന്ന് കരുതുന്നു. മനസ് പുറത്തേക്ക് പോയാൽ, അത് ദു:ഖം അനുഭവിക്കുന്നു. യാഥാർത്ഥ്യത്തിൽ, അതിന്റെ ആഗ്രഹങ്ങൾ പൂർത്തിയാകുമ്പോൾ, അത് തന്റെ സ്വന്തം സ്ഥലത്തേക്ക് മടങ്ങി, ആത്മാവിന്റെ സന്തോഷം അനുഭവിക്കുന്നു. സമാനമായി, ഉറക്കത്തിന്റെ, സമാധിയുടെ, മയക്കത്തിന്റെ അവസ്ഥകളിൽ, ആഗ്രഹിച്ച വസ്തു ലഭിക്കുമ്പോഴും, ഇഷ്ടമല്ലാത്ത വസ്തു നീക്കം ചെയ്യുമ്പോഴും, മനസ് അകത്തേക്ക് തിരിയുന്നു, ശുദ്ധമായ ആത്മാ-സന്തോഷം അനുഭവിക്കുന്നു. ഈ വിധത്തിൽ, മനസ് വിശ്രമമില്ലാതെ, ആത്മാവിൽ നിന്ന് പുറത്തേക്ക് പോകുകയും, പിന്നീടു തിരിച്ചും വരുകയും ചെയ്യുന്നു. മരം കീഴിൽ നിഴലാണ് സന്തോഷകരം; തുറന്നിടത്ത് ചൂട് കത്തിക്കുന്നു. സൂര്യന്റെ കിരണങ്ങളിൽ നടക്കുന്നതു വഴി ഒരു വ്യക്തി ഊഷ്മളതയിൽ നിന്ന് നിഴലിലേക്ക് എത്തുമ്പോൾ തണുപ്പിനെ അനുഭവിക്കുന്നു. നിഴലിൽ നിന്ന് സൂര്യത്തിലേക്ക്, പിന്നെ വീണ്ടും നിഴലിലേക്ക് പോകുന്നവൻ മൂഢനാണ്. ജ്ഞാനിയായ വ്യക്തി സ്ഥിരമായി നിഴലിൽ നിൽക്കുന്നു. അതുപോലെ, സത്യം അറിയുന്നവന്റെ മനസ്സ് ബ്രഹ്മനിൽ നിന്ന് വിട്ടുപോകുന്നില്ല. അറിവില്ലാത്തവന്റെ മനസ്സ്, അതിന്റെ വശത്ത്, ലോകത്തിൽ ചുറ്റുന്നു, ദു:ഖം അനുഭവിക്കുന്നു, കുറച്ച് സമയം ബ്രഹ്മനിലേക്ക് തിരിച്ചു വരുന്നു സന്തോഷം അനുഭവിക്കാൻ. യഥാർത്ഥത്തിൽ, ലോകം എന്നു പറയുന്നത് വെറും ചിന്തയാണ്. ലോകം ഇല്ലാതായാൽ, അഥവാ ചിന്ത ഇല്ലാതായാൽ, മനസ്സ് സന്തോഷം അനുഭവിക്കുന്നു; ലോകം പ്രത്യക്ഷപ്പെട്ടാൽ, അത് ദു:ഖത്തിലൂടെ കടക്കുന്നു.\n\nജ്ഞാനദൃഷ്ടി എന്താണ്?  \nശാന്തമായിരിക്കുകയാണ് ജ്ഞാനദൃഷ്ടി എന്ന് പറയുന്നത്. ശാന്തമായിരിക്കുകയെന്നത് ആത്മയിൽ മനസ്സിനെ സമാധാനിപ്പിക്കുകയാണ്. ടെലിപതി, ഭാവം, ഇന്നത്തെ സംഭവങ്ങൾ, ഭാവി സംഭവങ്ങൾ എന്നിവയും clairvoyance (ദർശനം) യും ജ്ഞാന-ദർശനമല്ല.  \n26. ആഗ്രഹരഹിതത്വവും ജ്ഞാനവും തമ്മിലുള്ള ബന്ധം എന്താണ്?  \nആഗ്രഹരഹിതത്വം ജ്ഞാനമാണ്. ഇവ രണ്ടും വ്യത്യസ്തമല്ല; ഇവ ഒരുപോലെ ആണ്. ആഗ്രഹരഹിതത്വം മനസ്സിനെ ഏത് വസ്തുവിലേക്കും തിരിയുന്നതിൽ നിന്ന് വിട്ടുനിൽക്കലാണ്. ജ്ഞാനം വസ്തുവിന്റെ അഭാവം ആണ്. മറ്റൊരുത്തനെ അന്വേഷിക്കാത്തത് ആത്മാവിനെ വിട്ടുനിൽക്കലോ ആഗ്രഹരഹിതത്വമോ ആണ്; ആത്മാവിനെ വിട്ടുപോകുന്നതല്ലെങ്കിൽ ജ്ഞാനമാണ്.  \n27. അന്വേഷണവും ധ്യാനവും തമ്മിലുള്ള വ്യത്യാസം എന്താണ്?  \nഅന്വേഷണം ആത്മാവിൽ മനസ്സിനെ നിലനിർത്തുന്നതിലാണ്. ധ്യാനം one\'s self ബ്രഹ്മൻ ആണ് എന്ന ചിന്തയിൽ ആണ്, അസ്തിത്വ-ചൈതന്യ-ആനന്ദം.  \n28. മുക്തി എന്താണ്?\\n\\nബദ്ധതയിൽ ഉള്ള ആത്മാവിന്റെ സ്വഭാവത്തെ അന്വേഷിച്ച്, തന്റെ യഥാർത്ഥ സ്വഭാവത്തെ തിരിച്ചറിയുക എന്നതാണ് മുക്തി. ശ്രീ രാമനർപ്പണം ആസ്തു.'
    ),
    Article(
        heading: 'സ്വയംയും അസ്വയംയും - മഹർഷി രാമന',
        body: 'അസ്തിത്വം അല്ലെങ്കിൽ ബോധം മാത്രമാണ് യാഥാർത്ഥ്യം. ബോധം കൂടിയുള്ള ഉണർവ് നാം ഉണർവെന്ന് വിളിക്കുന്നു. ബോധം കൂടിയുള്ള ഉറക്കം നാം ഉറക്കമായി വിളിക്കുന്നു. ബോധം കൂടിയുള്ള സ്വപ്നം നാം സ്വപ്നം എന്നു വിളിക്കുന്നു. ബോധം എല്ലാ ചിത്രങ്ങൾ വരും പോകും എന്നതിന്റെ സ്ക്രീനാണ്. സ്ക്രീൻ യാഥാർത്ഥ്യമാണ്, ചിത്രങ്ങൾ അതിൽ വെറും നിഴലുകൾ മാത്രമാണ്. ആത്മാവ് കൂടിയുള്ള പ്രത്യക്ഷതകൾ, നൂലിൽ ഉള്ള പാമ്പുപോലെ, ഇങ്ങനെ നന്നായി ഉദാഹരണമായി കാണിക്കാം. ഒരു സ്ക്രീൻ ഉണ്ട്. ആ സ്ക്രീനിൽ ആദ്യം ഒരു രാജാവിന്റെ രൂപം പ്രത്യക്ഷപ്പെടുന്നു. അദ്ദേഹം ഒരു ത throne നിൽക്കുന്നു. പിന്നീട് ആ തന്നെ സ്ക്രീനിൽ വിവിധ രൂപങ്ങളും വസ്തുക്കളും ഉള്ള ഒരു നാടകത്തിന് തുടക്കം കുറിക്കുന്നു, രാജാവ് സ്ക്രീനിൽ നാടകത്തെ കാണുന്നു. കാണുന്നവനും കാണപ്പെടുന്നവനും സ്ക്രീനിൽ വെറും നിഴലുകൾ മാത്രമാണ്, എല്ലാ ചിത്രങ്ങൾ പിന്തുണയ്ക്കുന്ന ഏക യാഥാർത്ഥ്യം. ലോകത്തിൽ, കാണുന്നവനും കാണപ്പെടുന്നവനും ചേർന്ന് മനസ്സിനെ രൂപീകരിക്കുന്നു, മനസ്സിന് ആത്മാവിൽ ആശ്രയം ലഭിക്കുന്നു. അജാത സ്കൂൾ ആദ്വൈതം പറയുന്നു, ‘ഒന്നിലധികം യാഥാർത്ഥ്യമില്ല. ജനനം അല്ലെങ്കിൽ മരണമില്ല, പ്രക്ഷിപ്തം അല്ലെങ്കിൽ ആകർഷണം ഇല്ല, സാദ്ധക (ആശയവാനായവൻ) ഇല്ല, മുമുക്ഷു (മുക്തി ആഗ്രഹിക്കുന്നവൻ) ഇല്ല, മുക്ത (മുക്തനായവൻ) ഇല്ല, അടിമത്തം ഇല്ല, മോക്ഷം ഇല്ല. ഏകത മാത്രം ശാശ്വതമായി നിലനിൽക്കുന്നു. ഈ സത്യത്തെ grasp ചെയ്യാൻ ബുദ്ധിമുട്ടുന്നവർക്കും, ‘ഞങ്ങൾ ചുറ്റുപാടുള്ള ഈ ഉറച്ച ലോകത്തെ എങ്ങനെ അവഗണിക്കാം?’ എന്ന് ചോദിക്കുന്നവർക്കും, സ്വപ്നാനുഭവം സൂചിപ്പിക്കുന്നു, ‘നിങ്ങൾ കാണുന്ന എല്ലാം കാണുന്നവനിൽ ആശ്രിതമാണ്’ എന്ന് അവരെ അറിയിക്കുന്നു. ദർശകനിൽ നിന്നു വേറെ കാണുന്നതൊന്നുമില്ല.’ ഇതിനെ ദൃശ്യ-സൃഷ്ടി വാദം എന്നു പറയുന്നു, അഥവാ ഒരാൾ ആദ്യം തന്റെ മനസ്സിൽ സൃഷ്ടിക്കുകയും, പിന്നീട് തന്റെ മനസ്സിൽ തന്നെ സൃഷ്ടിച്ചതു കാണുകയും ചെയ്യുന്നു എന്ന വാദം. ഇതിനെ grasp ചെയ്യാൻ കഴിയാത്തവർക്കും, ‘സ്വപ്നാനുഭവം വളരെ ചെറുതാണ്, എന്നാൽ ലോകം എപ്പോഴും ഉണ്ട്. സ്വപ്നാനുഭവം എനിക്ക് മാത്രം പരിമിതമായിരുന്നു. എന്നാൽ ലോകം എനിക്ക് മാത്രമല്ല, അനേകം ആളുകൾക്കും അനുഭവപ്പെടുകയും കാണപ്പെടുകയും ചെയ്യുന്നു, അതിനാൽ അത്തരത്തിലുള്ള ലോകത്തെ അസ്ഥിത്വമില്ലാത്തതെന്നു വിളിക്കാനാവില്ല’ എന്ന വാദം ഉന്നയിക്കുന്നവർക്കു, സൃഷ്ടി-ദർശന വാദം ഉത്തരം നൽകുന്നു, അവരെ ‘ദൈവം ആദ്യം ഇങ്ങനെ അങ്ങനെ ഒരു വസ്തു ഇങ്ങനെ അങ്ങനെ ഒരു ഘടകത്തിൽ നിന്നു സൃഷ്ടിക്കുകയും, പിന്നീട് മറ്റൊന്നും ഇങ്ങനെ തുടരും’ എന്നു പറയുന്നു. അതു മാത്രം അവരെ സംതൃപ്തമാക്കും. അവരുടെ മനസ്സുകൾ മറ്റൊരു വിധത്തിൽ സംതൃപ്തമല്ല, അവർ സ്വന്തം മനസ്സിൽ ചോദിക്കുന്നു, \'എങ്ങനെ എല്ലാ ഭൂഗോളവും, എല്ലാ ഭൂപടങ്ങളും, എല്ലാ ശാസ്ത്രങ്ങളും, നക്ഷത്രങ്ങളും, ഗ്രഹങ്ങളും, അവയെ നിയന്ത്രിക്കുന്ന അല്ലെങ്കിൽ ബന്ധപ്പെട്ടിരിക്കുന്ന നിയമങ്ങളും, എല്ലാ അറിവും പൂര്‍ണമായും അസത്യമായിരിക്കാം?\' ഇത്തരത്തിലുള്ളവർക്കു പറയേണ്ടത്, \'അതെ. ഈ എല്ലാം ദൈവം സൃഷ്ടിച്ചതാണ്, അതിനാൽ നിങ്ങൾ ഇത് കാണുന്നു.\' ഈ എല്ലാം കേൾവിക്കാരുടെ ശേഷിക്കനുസരിച്ചാണ് മാത്രം.\n\nഅബ്സോല്യൂട്ട് എപ്പോഴും ഒറ്റത്താണ്.\n\nആത്മയുടെ വെളുത്ത പ്രകാശം, അതിനെ അങ്ങനെ വിളിക്കാം, പ്രകാശത്തെയും ഇരുണ്ടതെയും മറികടക്കുന്നു. അതിൽ ഒരു വസ്തുവും കാണാൻ കഴിയുന്നില്ല. കാണുന്നവനും കാണുന്നവനും ഇല്ല. പിന്നെ, അവിടെ മുഴുവൻ ഇരുണ്ടതും (അവിദ്യ) ഉണ്ട്, അതിൽ വസ്തുക്കൾ കാണാൻ കഴിയുന്നില്ല. എന്നാൽ ആത്മാവിൽ നിന്നാണ് ഒരു പ്രതിഫലിത പ്രകാശം ഉത്ഭവിക്കുന്നത്, ശുദ്ധമായ മനസ്സിന്റെ (മനസ്) പ്രകാശം, ഈ പ്രകാശമാണ് ലോകത്തിന്റെ എല്ലാ ചിത്രങ്ങളുടെ അസ്തിത്വത്തിന് ഇടം നൽകുന്നത്, ഇത് മുഴുവൻ പ്രകാശത്തിലും മുഴുവൻ ഇരുട്ടിലും കാണപ്പെടുന്നില്ല, പക്ഷേ മാത്രം മൃദുവായ അല്ലെങ്കിൽ പ്രതിഫലിത പ്രകാശത്തിൽ മാത്രമാണ് കാണപ്പെടുന്നത്. ജ്ഞാനത്തിന്റെ (Jnana) അല്ലെങ്കിൽ യാഥാർത്ഥ്യത്തിന്റെ ദൃഷ്ടികോണത്തിൽ, ലോകത്തിൽ കാണുന്ന വേദന ഒരു സ്വപ്നമാണെന്ന് ഉറപ്പാണ്, ലോകം പോലെ, വിശേഷമായ വേദനകൾ, ഉദാഹരണത്തിന് ആഹാരക്കുറവ്, അനന്തമായ ഒരു ഭാഗമാണ്. സ്വപ്നത്തിൽ നിങ്ങൾ തന്നെ ആഹാരക്കുറവ് അനുഭവിക്കുന്നു. \n\nനിങ്ങൾ മറ്റുള്ളവരെ ആഹാരക്കുറവിൽ ദു:ഖിതരായി കാണുന്നു. നിങ്ങൾ നിങ്ങളെ തന്നെ ഭക്ഷ്യവസ്തുക്കൾ നൽകുന്നു, ദയയാൽ ആഹാരക്കുറവിൽ ദു:ഖിതരായ മറ്റുള്ളവരെ ഭക്ഷ്യവസ്തുക്കൾ നൽകുന്നു. സ്വപ്നം നീണ്ടുനിന്നപ്പോൾ, ആ എല്ലാ വേദനകളും നിങ്ങൾ ഇപ്പോൾ ലോകത്തിലെ വേദനയെ എങ്ങനെ കരുതുന്നുവോ അത്രയേറെ യാഥാർത്ഥ്യമായിരുന്നു. നിങ്ങൾ ഉണർന്നു വന്നപ്പോൾ മാത്രമാണ് നിങ്ങൾ സ്വപ്നത്തിലെ വേദന യാഥാർത്ഥ്യമല്ലെന്ന് കണ്ടെത്തിയത്. നിങ്ങൾ പൂർണ്ണമായും ഭക്ഷണം കഴിച്ചിട്ടുണ്ടാവാം, പിന്നെ ഉറങ്ങാൻ പോയിരിക്കുക. നിങ്ങൾ മുഴുവൻ ദിവസം കാഠിന്യത്തിൽ കഠിനമായി ജോലി ചെയ്യുന്നു, ക്ഷീണിതനും വിശക്കാനും ആഗ്രഹിക്കുന്ന സ്വപ്നം കാണുന്നു. പിന്നെ നിങ്ങൾ ഉണർന്നു, നിങ്ങളുടെ വയർ പൂർണ്ണമായിരിക്കുകയാണ്, നിങ്ങൾ നിങ്ങളുടെ കിടക്കയിൽ നിന്ന് നീങ്ങിപ്പോയിട്ടില്ല. എന്നാൽ, നിങ്ങൾ സ്വപ്നത്തിൽ ആയിരിക്കുമ്പോൾ, നിങ്ങൾ അനുഭവിക്കുന്ന വേദന യാഥാർത്ഥ്യമല്ല എന്ന പോലെ പ്രവർത്തിക്കാൻ കഴിയില്ല. സ്വപ്നത്തിലെ വിശപ്പിന് സ്വപ്നത്തിലെ ഭക്ഷണത്താൽ മാത്രം ശാന്തിയുണ്ടാക്കണം. സ്വപ്നത്തിൽ നിങ്ങൾ കണ്ട അത്ര വിശപ്പുള്ള സഹജീവികൾക്ക് ആ സ്വപ്നത്തിൽ ഭക്ഷണം നൽകേണ്ടതായിരുന്നു. നിങ്ങൾ സ്വപ്നവും ഉണർവിന്റെ അവസ്ഥയും തമ്മിൽ ഒരിക്കലും കലർത്താൻ കഴിയില്ല. ജ്ഞാനത്തിന്റെ അവസ്ഥയിൽ എത്തുകയും അതിനാൽ മായയിൽ നിന്നും ഉണരുകയും ചെയ്യുന്നതുവരെ, നിങ്ങൾ കാണുന്ന ദു:ഖം കുറയ്ക്കുന്നതിലൂടെ സാമൂഹ്യ സേവനം ചെയ്യണം. എന്നാൽ, അതും ആഹങ്കാരമില്ലാതെ, അഥവാ ‘ഞാൻ ചെയ്യുന്നു’ എന്ന ബോധം ഇല്ലാതെ, ‘ഞാൻ ഭഗവാന്റെ ഉപകരണമാണ്’ എന്ന അനുഭവത്തോടെ ചെയ്യണം. അതുപോലെ, ‘ഞാൻ എന്റെ താഴെയുള്ള ഒരാളെ സഹായിക്കുന്നു. അവൻ സഹായം ആവശ്യമാണ്. ഞാൻ സഹായിക്കാൻ കഴിയുന്ന സ്ഥിതിയിൽ ആകുന്നു. ഞാൻ ഉന്നതനാണ്, അവൻ താഴ്ന്നവനാണ്’ എന്ന ചിന്തയാൽ അഹങ്കാരിതരാകരുത്. എന്നാൽ, ആ മനുഷ്യനെ സഹായിക്കുന്നത്, ആ മനുഷ്യനിൽ ദൈവത്തെ ആരാധിക്കുന്ന ഒരു മാർഗമായി കാണണം. അത്തരത്തിലുള്ള എല്ലാ സേവനവും ആത്മാവിനായാണ്, മറ്റൊരാളിനായല്ല. നിങ്ങൾ മറ്റൊരാളെ സഹായിക്കുന്നതല്ല, നിങ്ങൾ മാത്രം നിങ്ങളെ സഹായിക്കുന്നതാണ്. കൈവല്യ നവനീതയിൽ മായയെക്കുറിച്ച് ആറു ചോദ്യങ്ങൾ ചോദിച്ചും ഉത്തരം നൽകിയും ഉണ്ട്. അവ ഉപദേശകമാണ്:\\n\\n1. മായ എന്താണ്? ഉത്തരം: ഇത് അനിർവചനീയമാണ്. എവിടെ നിന്നാണ് ഇത് വരുന്നത്? ഉത്തരം: അവൻ ഒരു വ്യത്യസ്തമായ സത്തയാണ് എന്ന് അനുഭവിക്കുന്ന മനസ്സിലോ എഗോയിൽ, \'ഞാൻ ഇത് ചെയ്യുന്നു\' അല്ലെങ്കിൽ \'ഇത് എന്റെതാണ്\' എന്ന് ചിന്തിക്കുന്നവനിലോ.\\n\\n3. ഇത് എവിടെ നിന്നാണ് വരുന്നത്, എങ്ങനെ ഇത് ഉത്ഭവിച്ചു? ഉത്തരം: ആരും പറയാൻ കഴിയില്ല.\\n\\n4. ഇത് എങ്ങനെ ഉത്ഭവിച്ചു? ഉത്തരം: വിചാരമില്ലായ്മ വഴി, \'ഞാൻ ആരാണ്?\' എന്ന് അന്വേഷിക്കാൻ പരാജയപ്പെട്ടതിലൂടെ.\\n\\n5. ആത്മയും മായയും ഇരുവരും ഉണ്ടെങ്കിൽ, ഇത് ആദ്വൈതത്തിന്റെ സിദ്ധാന്തത്തെ അസാധുവാക്കുന്നില്ലേ? ഉത്തരം: അത് ആവശ്യമില്ല, കാരണം മായ ആത്മാവിൽ ആശ്രിതമാണ്, ചിത്രം സ്ക്രീനിൽ ആശ്രിതമായിരിക്കുന്നതുപോലെ. ചിത്രം സ്ക്രീൻ യാഥാർത്ഥ്യമായിരിക്കുന്ന രീതിയിൽ യാഥാർത്ഥ്യമല്ല.\\n\\n6. ആത്മവും മായയും ഒന്നാണെങ്കിൽ, ആത്മാവ് മായയുടെ സ്വഭാവത്തിൽ ആണെന്ന് വാദിക്കാനാവില്ലേ, അതും ഭ്രമമായിരിക്കുമോ? ഉത്തരം: ഇല്ല, ആത്മാവ് ഭ്രമം സൃഷ്ടിക്കാൻ കഴിവുള്ളവനാണ്, എന്നാൽ അത് ഭ്രമമായിരിക്കേണ്ടതില്ല. ഒരു മന്ത്രവാദി നമ്മുടെ വിനോദത്തിനായി ആളുകൾ, മൃഗങ്ങൾ, വസ്തുക്കൾ എന്നിവയുടെ ഭ്രമം സൃഷ്ടിക്കാം, അവയെല്ലാം നാം അവനെ കാണുന്നതുപോലെ വ്യക്തമായി കാണുന്നു, എന്നാൽ പ്രകടനത്തിനുശേഷം അവൻ മാത്രം അവശേഷിക്കുന്നു, സൃഷ്ടിച്ച എല്ലാ ദൃശ്യങ്ങളും അപ്രത്യക്ഷമാകുന്നു. \n\nഅവൻ ദൃശ്യത്തിന്റെ ഭാഗമല്ല, എന്നാൽ ഉറച്ചതും യാഥാർത്ഥ്യവുമായതുമാണ്.\n\nസൃഷ്ടിയെ വിശദീകരിക്കാൻ പുസ്തകങ്ങൾ താഴെക്കൊടുത്തിരിക്കുന്ന ഉദാഹരണം ഉപയോഗിക്കുന്നു: ആത്മാവ് ഒരു ചിത്രത്തിന്റെ കനവാസിനെപ്പോലെയാണ്. ആദ്യം, കനവാസിലെ ചെറിയ തുരപ്പുകൾ അടയ്ക്കാൻ ഒരു പേസ്റ്റ് പുരട്ടുന്നു. ഈ പേസ്റ്റ് എല്ലാ സൃഷ്ടികളിലും ഉള്ള ആന്തര്യാമിനോട് (Antaryamin) താരതമ്യപ്പെടുത്താം. പിന്നീട് കലാകാരൻ കനവാസിൽ ഒരു രൂപരേഖ വരയ്ക്കുന്നു. ഇത് എല്ലാ ജീവികളുടെയും സൂക്ഷ്മശരീരം (sukshma sarira) എന്നതുമായി താരതമ്യപ്പെടുത്താം; ഉദാഹരണത്തിന്, എല്ലാ വസ്തുക്കളും ഉദ്ഭവിക്കുന്ന പ്രകാശവും ശബ്ദവും (bindu and nada) ആണ്. ഈ രൂപരേഖയിൽ കലാകാരൻ തന്റെ ചിത്രത്തെ നിറങ്ങളാൽ വരയ്ക്കുന്നു, തുടങ്ങിയവ, ഇത് ലോകത്തെ നിർമ്മിക്കുന്ന ഭൗതിക രൂപങ്ങളെ താരതമ്യം ചെയ്യാവുന്നതാണ്. വെദാന്തം പറയുന്നു, സൃഷ്ടി കാണുന്നവനോടൊപ്പം ഒരേസമയം ദൃശ്യമാകുന്നു. ഘട്ടങ്ങളിലോ പടികളിലോ സൃഷ്ടിയില്ല. അനുഭവിക്കുന്നവനും അനുഭവത്തിന്റെ വസ്തുക്കളും ഒരേസമയം ഉണ്ടാകുന്ന സ്വപ്നത്തിലെ സൃഷ്ടിയെപ്പോലെയാണ് ഇത്. ഈ വിശദീകരണത്തിൽ സംതൃപ്തരാകാത്തവർക്കായി, ക്രമിക സൃഷ്ടിയുടെ സിദ്ധാന്തങ്ങൾ പുസ്തകങ്ങളിൽ അവതരിപ്പിക്കപ്പെടുന്നു. ലോകത്തിന്റെ അസ്തിത്വം നിഷേധിക്കുന്നുവെന്ന് അദ്വൈതികളുടെ ശങ്കര സ്കൂളിന്റെ ആളുകൾ പറയുന്നു എന്നത് ശരിയല്ല, അല്ലെങ്കിൽ അവർ അതിനെ അസത്യമായി വിളിക്കുന്നു. മറ്റു വശത്തേക്ക്, അവർക്കു മറ്റുള്ളവരേക്കാൾ കൂടുതൽ യാഥാർത്ഥ്യമാണിത്. അവരുടെ ലോകം എപ്പോഴും നിലനിൽക്കും, എന്നാൽ മറ്റു പാഠശാലകളുടെ ലോകത്തിന് ഉത്ഭവം, വളർച്ച, നാശം എന്നിവയുണ്ടാകും, അതിനാൽ അത് യാഥാർത്ഥ്യമല്ല. അവർ \'ലോകം\' എന്ന നിലയിൽ ലോകം യാഥാർത്ഥ്യമല്ല എന്ന് മാത്രം പറയുന്നു, എന്നാൽ ബ്രഹ്മൻ എന്ന നിലയിൽ ലോകം യാഥാർത്ഥ്യമാണെന്ന് പറയുന്നു. എല്ലാം ബ്രഹ്മൻ ആണ്, ബ്രഹ്മനിൽ ഒഴികെ ഒന്നും ഇല്ല, ബ്രഹ്മൻ എന്ന നിലയിൽ ലോകം യാഥാർത്ഥ്യമാണു. \n\nആത്മൻ എപ്പോഴും നിലനിൽക്കുന്ന ഏക യാഥാർത്ഥ്യമാണ്, എല്ലാ മറ്റ് കാര്യങ്ങൾ അതിന്റെ വെളിച്ചത്തിൽ മാത്രമേ കാണപ്പെടുന്നുള്ളു. നാം അതിനെ മറന്നുപോകുകയും രൂപത്തെക്കുറിച്ച് മാത്രം ശ്രദ്ധ കേന്ദ്രീകരിക്കുകയും ചെയ്യുന്നു. ഹാളിൽ ഉള്ള വെളിച്ചം ആളുകൾ ഉണ്ടാകുമ്പോഴും ഇല്ലായ്കുമ്പോഴും, നാടകത്തിലേക്കു പോകുമ്പോഴും, ഒന്നും നടക്കാത്തപ്പോൾ പോലും ജ്വലിക്കുന്നു. ഹാൾ, ആളുകൾ, നാടകങ്ങൾ എന്നിവയെ കാണാൻ നമ്മെ സഹായിക്കുന്ന വെളിച്ചമാണ് അത്. നാം പ്രകാശം വെളിപ്പെടുത്തുന്ന വസ്തുക്കളിലോ രൂപങ്ങളിലോ അത്ര തന്നെ engrossed ആയിരിക്കുന്നു, പ്രകാശത്തിലേക്കുള്ള ശ്രദ്ധ നാം നൽകുന്നില്ല. വസ്തുക്കൾ പ്രത്യക്ഷപ്പെടുന്ന ജാഗ്രതയിലോ സ്വപ്നാവസ്ഥയിലോ, ഒന്നും കാണാത്ത ഉറക്കാവസ്ഥയിലോ, എല്ലായ്പ്പോഴും സാക്ഷിയുടെ അല്ലെങ്കിൽ ആത്മയുടെ പ്രകാശം ഉണ്ടാവുന്നു, എല്ലായ്പ്പോഴും കത്തുന്ന ഹാൾ ലാമ്പ് പോലെയാണ്. കാണുന്നവനിൽ ശ്രദ്ധ കേന്ദ്രീകരിക്കേണ്ടതാണ്, കാണുന്നതിൽ അല്ല, വസ്തുക്കളിൽ അല്ല, അവയെ വെളിപ്പെടുത്തുന്ന പ്രകാശത്തിൽ ആണ്. \n\nലോകത്തിന്റെ യാഥാർത്ഥ്യത്തെക്കുറിച്ചുള്ള ചോദ്യങ്ങൾ, ലോകത്തിൽ വേദനയോ ദുർഭിക്ഷമോ ഉള്ളതിനെക്കുറിച്ചുള്ള ചോദ്യങ്ങൾ, \'ഞാൻ ആരാണ്?\' എന്ന് അന്വേഷിക്കുമ്പോൾ അവസാനിക്കും, കാണുന്നവനെ കണ്ടെത്തുമ്പോൾ. കാണുന്നവൻ ഇല്ലാതെ, alleged ആയ ലോകവും അതിന്റെ ദുർബലതകളും ഉണ്ടാവുന്നില്ല. \n\nലോകം അഞ്ചു ഇന്ദ്രിയ വസ്തുക്കളുടെ രൂപത്തിലാണ്, മറ്റൊന്നുമില്ല. ഈ അഞ്ച് തരത്തിലുള്ള വസ്തുക്കൾ അഞ്ചു ഇന്ദ്രിയങ്ങൾ വഴി അനുഭവപ്പെടുന്നു. ഈ അഞ്ചു ഇന്ദ്രിയങ്ങൾ വഴി മനസ്സിലൂടെ എല്ലാം തിരിച്ചറിയപ്പെടുന്നതിനാൽ, ലോകം മനസ്സിന് പുറമേ ഒന്നുമല്ല. മനസ്സിന് പുറത്ത് ഒരു ലോകമുണ്ടോ?\\n\\nലോകവും ബോധവും ഒരുമിച്ച് ഉദയിക്കുകയും അപ്രത്യക്ഷമാകുകയും ചെയ്യുമ്പോൾ, ലോകം ബോധത്തിലൂടെ മാത്രമേ പ്രകാശിക്കുകയോ അനുഭവപ്പെടുകയോ ചെയ്യൂ. ഈ രണ്ടും ഉദയിക്കുകയും അപ്രത്യക്ഷമാകുകയും ചെയ്യുന്ന ഉറവിടം, അത് തന്നെ കാണപ്പെടുകയോ അപ്രത്യക്ഷമാകുകയോ ചെയ്യാത്തത്, ആധ്യാത്മികമായ യാഥാർത്ഥ്യമാണ്.\\n\\nഎല്ലാ അറിവിന്റെയും പ്രവർത്തനത്തിന്റെയും ഉറവിടമായ മനസ്സ് നിശ്ചലമാകുമ്പോൾ, ലോകത്തിന്റെ ദർശനം അവസാനിക്കും. യഥാ യാഥാർത്ഥ്യമായ ദോശയുടെ അറിവ് സൃഷ്ടിച്ച പാമ്പിന്റെ കാഴ്ച ഇല്ലാതാകുന്നതുവരെ ഉദയം വരില്ല, അതുപോലെ സൃഷ്ടിച്ച ലോകത്തിന്റെ കാഴ്ച ഉപേക്ഷിക്കാതെ യാഥാർത്ഥ്യത്തിന്റെ അനുഭവം കൈവരിക്കാനാവില്ല. \n\nയഥാർത്ഥത്തിൽ ഉള്ളത് മാത്രം ആത്മയാണ്. ലോകം, ജിവ (വ്യക്തിഗത ആത്മാവ്)യും ഈശ്വര (ദൈവം)യും മാനസിക സൃഷ്ടികളാണ്, മുത്തിന്റെ മുത്തിൽ വെള്ളിയുടെ പ്രത്യക്ഷത പോലെയാണ്. ഇവ എല്ലാം ഒരേ സമയം പ്രത്യക്ഷപ്പെടുകയും സമാനമായി ഇല്ലാതാവുകയും ചെയ്യുന്നു. ആത്മാവാണ് ലോകം, എഗോയും ഈശ്വരയും.\n\nജ്ഞാനിക്ക് ലോകം പ്രത്യക്ഷപ്പെടുന്നുണ്ടോ എന്നത് പ്രാധാന്യമില്ല. അത് പ്രത്യക്ഷപ്പെടുന്നുണ്ടോ എന്നതിനെക്കുറിച്ച് അവന്റെ ശ്രദ്ധ എപ്പോഴും ആത്മത്തിലേക്കാണ്. അക്ഷരങ്ങളും അവയെ അച്ചടിച്ച കാഗിതവും എടുക്കുക.\n\nനിങ്ങൾ മുഴുവൻ അക്ഷരങ്ങളിൽ engrossed ആകുന്നു, കാഗിതത്തിനായി നിങ്ങൾക്ക് ശ്രദ്ധയില്ല. എന്നാൽ ജ്ഞാനി അക്ഷരങ്ങൾ ഉണ്ടാകുകയോ ഇല്ലയോ എന്നതിനെക്കുറിച്ച് ആലോചിക്കാതെ പേപ്പർ മാത്രമാണ് യാഥാർത്ഥ്യമായ അടിത്തറ എന്ന് കരുതുന്നു. \n\nനിങ്ങൾ വിവിധ ഘടകങ്ങളിൽ നിന്നുള്ള വിവിധ രൂപങ്ങളിൽ എല്ലാ തരത്തിലുള്ള മിഠായികൾ ഉണ്ടാക്കുന്നു, അവയിൽ എല്ലാം മധുരമുള്ളതുകൊണ്ടാണ്, കാരണം അവയിൽ എല്ലാം പഞ്ചസാര ഉണ്ട്, മധുരം പഞ്ചസാരയുടെ സ്വഭാവമാണ്. അതുപോലെ, എല്ലാ അനുഭവങ്ങളും അവയുടെ അഭാവവും ആത്മാവിന്റെ സ്വഭാവമായ പ്രകാശം ഉൾക്കൊള്ളുന്നു. ആത്മാവില്ലാതെ അവ അനുഭവിക്കാനാവില്ല, പഞ്ചസാര ഇല്ലാതെ നിങ്ങൾ ഉണ്ടാക്കുന്ന ഒരു വസ്തുവും മധുരമുള്ളതാകില്ല.\n\nസാന്നിധ്യമുള്ള സത്തയെ ഇശ്വരൻ എന്ന് വിളിക്കുന്നു. സാന്നിധ്യം മായയോടുകൂടിയാണ്. അത് (ഇശ്വരൻ) മായയോടുകൂടിയ സത്തയുടെ ജ്ഞാനമാണ്. സൂക്ഷ്മമായ അഭിമാനം ഹിരണ്യഗർഭത്തിൽ നിന്ന് ഉയരുന്നു; ഹിരണ്യഗർഭത്തിൽ നിന്ന് ഭൗതിക, കൃത്യമായ വിരാട് ഉയരുന്നു. ചിത്ആത്മാ ശുദ്ധമായ സത്ത മാത്രമാണ്. ലോകത്തിൽ വേദനയുടെ അസ്തിത്വത്തെക്കുറിച്ച്, ജ്ഞാനിയൻ തന്റെ അനുഭവത്തിൽ നിന്ന് വിശദീകരിക്കുന്നു, ആത്മയിൽ അകത്തേക്ക് പിന്മാറുമ്പോൾ എല്ലാ വേദനയുടെയും അവസാനമുണ്ടാവും. വേദന, വസ്തു സ്വയം നിന്ന് വ്യത്യസ്തമായിരിക്കുമ്പോൾ മാത്രം അനുഭവപ്പെടുന്നു. എന്നാൽ ആത്മാവ് ഒരു അഖണ്ഡമായ സമ്പൂർണതയായി കണ്ടെത്തുമ്പോൾ, അനുഭവിക്കാൻ ആരും എന്തുമുണ്ടോ? \n\nഉപനിഷത്തിലെ ‘ഞാൻ ബ്രഹ്മൻ’ എന്ന വാചകം, ബ്രഹ്മൻ ‘ഞാൻ’ എന്ന രൂപത്തിൽ അസ്തിത്വം ഉള്ളതാണെന്ന് മാത്രമാണ് സൂചിപ്പിക്കുന്നത്.'
    ),
    Article(
        heading: 'മഹർഷി രാമണന്റെ യോഗത്തിന്റെ എട്ട് അസ്ഥികൾ',
        body: 'D: അറിവിന്റെ എട്ട് അസ്ഥികൾ (ജ്ഞാന അഷ്ടാംഗ) എന്താണ്?\\n\\nM: എട്ട് അസ്ഥികൾ മുമ്പ് പരാമർശിച്ചവയാണ്, അതായത്, യമ, നിയമ എന്നിവ, പക്ഷേ വ്യത്യസ്തമായി നിർവചിച്ചിരിക്കുന്നു:\\n\\n(1) യമ: ഇത് ഇന്ദ്രിയങ്ങളുടെ സമാഹാരത്തെ നിയന്ത്രിക്കുന്നതാണ്, ശരീരം എന്നിവയുമായി ബന്ധപ്പെട്ട ലോകത്തിൽ ഉള്ള ദോഷങ്ങൾ തിരിച്ചറിയുന്നതാണ്.\\n\\n(2) നിയമ: ഇത് ആത്മാവുമായി ബന്ധപ്പെട്ട മാനസികാവസ്ഥകളുടെ ഒരു പ്രവാഹം നിലനിർത്തുന്നതും, വിരുദ്ധമായ അവസ്ഥകളെ തള്ളുന്നതുമാണ്. മറ്റൊരു വാക്കിൽ, ഇത് പരമാത്മനോടുള്ള നിരന്തരമായ പ്രണയം എന്നർത്ഥമാണ്. \n\n(3) ആസന: ബ്രഹ്മന്റെ മേൽ സ്ഥിരമായ ധ്യാനം എളുപ്പത്തിൽ സാധ്യമാക്കുന്ന സഹായമാണ് ആസന. \n\n(4) പ്രാണായാമ: റെചക (ശ്വാസം പുറത്താക്കൽ) എന്നത് ലോകത്തെ, ശരീരത്തെ എന്നിവയെ രൂപവും നാമവും എന്ന രണ്ട് അസത്യമായ വശങ്ങൾ നീക്കം ചെയ്യുകയാണ്, പൂരക (ശ്വാസം ആകർഷണം) എന്നത് ആ വസ്തുക്കളിൽ സ്ഥിരമായ മൂന്നു സത്യമായ വശങ്ങൾ, അസ്തിത്വം, ബോധം, ആനന്ദം എന്നിവയെ പിടികൂടുകയാണ്, കുംബhaka എന്നത് ഈ വശങ്ങളെ കൈവശമാക്കുകയാണ്. \n\n(5) പ്രത്യാഹാര: ഇത് മനസ്സിൽ വീണ്ടും പ്രവേശിക്കാൻ അനുവദിക്കാതെ നാമവും രൂപവും നീക്കം ചെയ്യുകയാണ്. \n\n(6) ധാരണ: ഇത് മനസ്സിനെ ഹൃദയത്തിൽ നിലനിര്‍ത്തുകയാണ്, പുറത്തേക്ക് തിരിഞ്ഞുപോകാതെ, ഒരാൾ അസ്തിത്വം-ബോധം-ആനന്ദം എന്നത് തന്നെയാണ് എന്നത് തിരിച്ചറിഞ്ഞുകൊണ്ട്. \n\n(7) ധ്യാനം: ഞാൻ വെറും ശുദ്ധ ബോധമാണ് എന്ന രൂപത്തിൽ ധ്യാനം. അത്, അഞ്ചു ഷീഥുകൾ അടങ്ങിയ ശരീരം വിട്ട്, ഒരാൾ \'ഞാൻ ആരാണ്?\' എന്ന ചോദ്യം ചോദിക്കുന്നു, അതിന്റെ ഫലമായി, \'ഞാൻ\' എന്ന നിലയിൽ നിലനിൽക്കുന്നു, അത് ആത്മാവ് എന്ന നിലയിൽ പ്രകാശിക്കുന്നു. ഈ വിജ്ഞാനം ആത്മാവിനെയും അനാത്മാവിനെയും സംബന്ധിച്ചാണ് മാത്രമല്ല, അതിന്റെ സ്വയം തന്നെയല്ല. ഇത് ആത്മാവിനോട് ബന്ധപ്പെട്ടപ്പോൾ, ഇത് സത്യജ്ഞാനം എന്ന് വിളിക്കപ്പെടുന്നു, ആത്മാവിന്റെ വസ്തുവായ ആ മാനസിക രൂപത്തിൽ ഉള്ള ജ്ഞാനം, അല്ലെങ്കിൽ ഏകത്വം (ആത്മാവ്) ഉള്ളതിന്റെ ഉള്ളടക്കമുള്ള ജ്ഞാനം; എന്നാൽ ഇത് അനാത്മാവിനെ സംബന്ധിച്ചപ്പോൾ, ഇത് അജ്ഞാനം എന്ന് വിളിക്കപ്പെടുന്നു. ആത്മാവിനെ സംബന്ധിച്ച ഈ വിജ്ഞാനത്തിന്റെ അവസ്ഥ, ആത്മാവിന്റെ രൂപത്തിൽ പ്രകാശിക്കുന്നപ്പോൾ, \'ഞാൻ-പ്രകാശനം\' എന്ന് പറയപ്പെടുന്നു. ഈ പ്രകാശനം യാഥാർത്ഥ്യത്തിൽ (അത്, ആത്മാവ്) നിന്നും വേർപെടുത്തി നടക്കാൻ കഴിയില്ല. ഈ പ്രത്യക്ഷീകരണം യാഥാർത്ഥ്യത്തിന്റെ നേരിട്ടുള്ള അനുഭവത്തിന് അടയാളമായി serves ചെയ്യുന്നു. എന്നാൽ, ഇത് സ്വയം യാഥാർത്ഥ്യമായിരിക്കാനുള്ള അവസ്ഥയെ രൂപീകരിക്കാൻ കഴിയില്ല. ഈ പ്രത്യക്ഷീകരണം സംഭവിക്കുന്നതിൽ ആശ്രയിക്കുന്നതാണ് അടിസ്ഥാന യാഥാർത്ഥ്യം, ഇത് പ്രജ്ഞാനമായി വിളിക്കപ്പെടുന്നു. വെദാന്തിക ഗ്രന്ഥമായ \'പ്രജ്ഞാനം ബ്രഹ്മ\' ഈ സത്യത്തെ പഠിപ്പിക്കുന്നു.\n\nഈ scripture-ന്റെ അർത്ഥം ഇതായി അറിയുക. സ്വയം പ്രകാശമാനവും എല്ലാത്തിനും സാക്ഷിയുമായ ആ ആത്മാവ് വിജ്ഞാനകോശത്തിൽ (ബുദ്ധിയുടെ കവചത്തിൽ) താമസിക്കുന്നതായി പ്രത്യക്ഷപ്പെടുന്നു.\n\nഭാവനാത്മകമായ രീതിയിൽ, ഈ ആത്മാവിനെ നിങ്ങളുടെ ലക്ഷ്യമായി പിടിച്ചെടുക്കുകയും അത് ആത്മമായി ആസ്വദിക്കുകയും ചെയ്യുക.'
    ),
  ],
);
